quests[25161] = { id = 25161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogrezonians in the Mood", description = "I was supposed to receive a shipment of jasper from Azeroth Express, but I just heard their ship crashed into some tiny island called Ogrezonia.  I worry about the crew, as the giant female ogres on the island are rumored to perform horrible rituals on men who happen upon their island.  My work must go on, though, and we need those gems.  I've heard great things about your skill as a jewelcrafter - could you deliver three jagged jaspers by the end of the day?", sourceObjective = "Cut three Jagged Jaspers and give them to Marith Lazuria in Orgrimmar.", progress = "Have you brought me the gems I need?", completion = "Your work is as good as it is rumored to be!", sourceObjectiveStatus = "unverified-source-field" }
quests[25162] = { id = 25162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Goo", description = "Instead of using the tired old method of setting gems into rings and such, I use an innovative new method.  I simply glue on the gems with Vernstrom Elemental Glue!  The doctor needs more elemental goo for another batch, though, and I have a whole bunch of setting to do.  Can you go get me some?", sourceObjective = "Collect 10 Elemental Goo from any Cataclysm elemental and bring them to Marith Lazuria in Orgrimmar.", progress = "Did you bring me the elemental goo?", completion = "Thanks.  Erm.  Just set them over there.  I need to figure out how to get my hand off of this jar�", sourceObjectiveStatus = "unverified-source-field" }
quests[25163] = { id = 25163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Did This?", description = "Sabotage! It had to be. The whole fortress magazine exploded. The Horde must've gotten someone inside...\n\n{class}, if you've the stones to rush into that burning nightmare... look for some clues as to who did this to us. The General will want to know! Look for a Horde corpse in the wreckage and get to the bottom of this disaster...", sourceObjective = "Look for a Horde corpse within Bael'dun Keep.", completion = "<One smoldering corpse stands out amidst the carnage. The dead goblin clutches the schematics of the fortress in his lifeless hand...>\n\n<The Bilgewater Cartel goblins. They did this!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25164] = { id = 25164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backed Into a Corner", description = "The naga are upon us, {class}. Aid us in fightin' dem off!", sourceObjective = "Defend the Earthen Ring camp until the naga retreat.", progress = "Dey seem relentless, but we gonna turn dem back!", completion = "I'm glad you were here, mon.\n\nToshe be lookin' like he wants to chase dem down. You should go help'em.", sourceObjectiveStatus = "unverified-source-field" }
quests[25165] = { id = 25165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Trust a Big Barb and a Smile", description = "Next, we gonna get some poison from the scorpions that be runnin' around here.  But don't you worry, Bom'bay's not gonna let you get hurt!\n\nBom'bay's got a big totem that you gonna stick in the ground when the scorpion strikes.  The totem gonna suck up all the poison, and you gonna walk away still breathing.  Sound good?", sourceObjective = "Obtain 6 samples of Scorpid Venom by placing the Poison Extraction Totem near a Clattering Scorpid.", completion = "This is it!  The scorpid juju Bom'bay been waitin' for!  Now we gonna fix you right up, {class}.\n\nYou come back to Bom'bay when you be needin' a pickup.  Bom'bay got the spells to fix ya!", sourceObjectiveStatus = "unverified-source-field" }
quests[25166] = { id = 25166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Dreadbeard", description = "This is getting pretty fun, but let's not forget we're here for Gnomeregan!\n\nWe spotted the captain of the Southsea over on one of his boats to the south, past where all the fighting is. He's all alone on his little boat, undefended!\n\nIf you go take care of him, we'll have the rest of these pirates mopped up in no time.", sourceObjective = "Kill Captain Dreadbeard.", progress = "My patience is beginning to wear thin. I don't have enough time to wait around for you, so kill that captain already.\n\nUm, I mean, please? Tee-hee?", completion = "He was controlling a sea giant? Fascinating. If we'd managed to investigate further...\n\nOh, I mean, wow, that's totally crazy! But thank goodness he's gone, hooray! Mister Noggenfogger will be so pleased.\n\nHere's a nice big reward, you!", sourceObjectiveStatus = "unverified-source-field" }
quests[25167] = { id = 25167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Chain", description = "Aw man, this ain't good.  Not one bit, mon.\n\nThrall's off to sea, Vol'jin's taking care of business in Echo Isles, and old Master Gadrin is left behind to take care of Sen'jin.  And then what happens?  Those humans come outta Northwatch Hold and set up camp in our backyard!\n\nLucky for us, they just got here, and they're still setting up their base.  You can help out old Gadrin by destroying those big supply crates they carry, and by killing the laborers carryin' them. You'll find'm to the southwest.", sourceObjective = "Destroy 3 Northwatch Supply Crates and kill 10 Northwatch Lugs.", progress = "We gotta get rid of these humans, {class}.", completion = "Well, we've stymied their efforts for now, but they're still here.  We'll have to press on, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25168] = { id = 25168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purge the Valley", description = "Northwatch is a highly-defended stronghold southwest of here, across the harbor.  It's a strategically-located stronghold that the Horde still struggles to overtake.  We don't need the humans setting up another Northwatch here in Durotar.\n\nSweep through the valley to the west and slay these humans, {name}.  Let them know the power and the fury of Sen'jin.", sourceObjective = "Defeat 12 Northwatch troops in Northwatch Foothold.", completion = "A battle well-fought, {class}, but I still have my doubts about our effectiveness.  These humans don't seem to be going anywhere.\n\nYou, however, have done more than could reasonably be asked of any loyal member of the Horde.  Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25169] = { id = 25169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War of Northwatch Aggression", description = "These humans in the west, they don't just wanna camp out in Durotar, mon.  They got bigger plans, and those plans involve takin' our home and leavin' our skulls on pikes.\n\nWell I'm not havin' it.  Nope!  Not Lar!  I've got family here in Sen'jin, and I'll be damned if I let one of those brutes put my Tai'tasi's head on a stick!\n\nThey've got their plans written down in there, mon.  Big scrolls, real important-lookin'.  We gonna burn those scrolls before they burn us.", sourceObjective = "Destroy the 3 sets of Attack Plans held within Northwatch Foothold.", progress = "Destroy those humans, {name}.", completion = "Good work, hero.  You done good for Sen'jin today.  No... you done good for all of Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[25170] = { id = 25170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Up the Coastline", description = "Heya mon!  Bom'bay be workin' on some new mojo.  You wanna try a piece of it?  Well, before ya do, Bom'bay's gonna need ya to pick up some jujus.\n\nFirst, Bom'bay needs ya to get some o' the goop from the crabs down by the water.  Let me see your hands!\n\n<Bom'bay examines your hands closely.>\n\nBom'bay gonna need 5 handfuls.  Go on now!", sourceObjective = "Obtain 5 handfuls of Crawler Mucus.", progress = "You bring the jujus, I show you my mojo.", completion = "Ya mon, that's tha stuff.  Now we get the other jujus.", sourceObjectiveStatus = "unverified-source-field" }
quests[25171] = { id = 25171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding On", description = "We gotta pass the word on to Razor Hill.  These humans may be defeated today, but tomorrow they'll come again, and when they do, we'll need help from the orcs.\n\nSpeak with Jhash, outside the gates of Sen'jin.  He'll give you a ride to Razor Hill.  His wolves know the path well.", sourceObjective = "Speak to Raider Jhash to get a ride to Razor Hill. Once there, speak with Gar'thok.", completion = "That troll wants us to send help?  Bah, he can forget it.  I've got my own human problems to worry about, and even those are the least of my worries right now.\n\nSen'jin Village is right next to Echo Isles and the Valley of Trials.  Old Gadrin should find plenty of youngbloods to help him with his human infestation.", sourceObjectiveStatus = "unverified-source-field" }
quests[25172] = { id = 25172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invaders in Our Home", description = "You're not just another grunt - you seem to be a serious {class}.  Good, because that's exactly what I need.\n\nTry not to let the word out, since I don't want to cause a panic... but there have been reports of more humans nearby.  This is an egregious betrayal of the peace that we negotiated with that miserable Jaina Proudmoore!  We can't allow humans here in Durotar, and especially not here in the Valley.\n\nYou will find them to the south.  Slay them quickly, before their numbers increase any more.", sourceObjective = "Slay 7 Northwatch Scouts.", completion = "Executed with quickness and discretion.  A job well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[25173] = { id = 25173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Bad to Worse", description = "Tiragarde Keep lies to the southeast of here, on Durotar's eastern shore.  You probably passed it on your trip from Sen'jin Village.  This castle has been a thorn in my side for too long.\n\nHumans from Kul Tiras lived in the castle for years, thwarting my every attempt to crush them.  When the cataclysm hit us, the shore was wiped out, along with the castle and all the humans.  However, these upstarts from Northwatch have moved in to take their place!\n\n<Gar'Thok roars in aggravation.>", sourceObjective = "Kill 6 Northwatch Marines, 6 Northwatch Sharpshooters, and Lieutenant Palliter in Tiragarde Keep.", completion = "Word of your bravery travels fast, {class}. Tales of your victory at Tiragarde Keep will be heralded in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[25174] = { id = 25174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twinbraid Needs to Know", description = "<General Twinbraid will want to know the details of this cowardly attack. You gather up the evidence.>", sourceObjective = "Report to General Twinbraid at Twinbraid's Patrol in Southern Barrens.", completion = "What... WHAT!?\n\nBael'dun in ruins? Corpses everywhere - no. No!\n\n<You describe the evidence you found at the scene.>\n\nThe Bilgewater goblins, was it? They want a fight do they? We'll show 'em what it means to be a part of the Horde, we will. I'll fill the Battlescar with their corpses. I'll redden the dirt with their blood.\n\n<Twinbraid grabs you by the collar.>\n\nGoblins. Are going. To die!", sourceObjectiveStatus = "unverified-source-field" }
quests[25175] = { id = 25175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bad News", description = "<You gently close Marley's eyes.>\n\n<Someone is going to have to tell General Twinbraid that the Horde has killed his only son.>\n\n<That someone is you.>", sourceObjective = "Bring the bad news to General Twinbraid at Twinbraid's Patrol in Southern Barrens.", completion = "<General Twinbraid hurls his axeblade into the dirt, his voice quiet but his body quivering with disbelief and rage.>\n\nThat was my boy, {name}. My only boy.\n\nThey've made it personal, {class}. Personal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25176] = { id = 25176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploiting the Situation", description = "<Hey there, handsome!  I've had my eye on those big, beefy biceps ever since you stepped into town./What're you looking at> ugly?  I've seen you walking around Razor Hill, trying to steal MY men from me!;\n\nListen, I've got something for you to do.  I hear Gar'Thok's got you headed over to Tiragarde.  While you're there, think you could find some abandoned Kul Tiras knicknacks?\n\n<Thanks sweetie!/Don't ask why> just get to it!;", sourceObjective = "Obtain 6 pieces of Kul Tiras Treasure.", progress = "<Gail purrs disarmingly at you.>", completion = "You brought me my treasure!  What a sweetheart!", sourceObjectiveStatus = "unverified-source-field" }
quests[25177] = { id = 25177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storming the Beaches", description = "Now that those humans are out of our hair for a bit, we can move on to more pressing matters.\n\nThe cataclysm utterly decimated Durotar's eastern coast.  You saw the wreckage that it made of Tiragarde.  The devastation was even worse on the coast to the east of here.\n\nAfter the first wave, the beach was overtaken by angry elementals that came from the sea.  I sent grunts to take care of it, but the onslaught was too much.  I'm guessing you'll have a little more luck than they did.\n\nBeware the tides!", sourceObjective = "Kill 11 Foaming Sea Elementals.", completion = "The scent of the sea hangs about you, {name}.  Your efforts may have purchased another day for Razor Hill.\n\nI will pass word of your deeds up my chain of command.  You have our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[25178] = { id = 25178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipwreck Searching", description = "<Hey handsome, welcome back!  You wouldn't mind running another errand, would you?  I'd be EVER so grateful.../You!  Stop right there> you tramp!  I'm not finished with you yet.;\n\nI hear you're headed off to the shore east of here.  The beach is filled with crashed ships, and those ships have gnomish tools in them... tools that I can use.\n\n<See you soon, beefcake!/Get cracking> missy!;", sourceObjective = "Obtain 4 sets of Gnomish Tools.", progress = "Has my knight in shining armor returned?", completion = "You really know how to treat a girl, you know that?  If you ever need anything...", sourceObjectiveStatus = "unverified-source-field" }
quests[25179] = { id = 25179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loss Reduction", description = "You've got to help us.  The elementals... they're stronger than they look, and they come in waves.  They took us completely by surprise, and we were overcome.\n\nMany of my fellow grunts lay dying on the beach.  If you could save them... I would be grateful, as would Gar'Thok back in Razor Hill.", sourceObjective = "Rescue 4 Injured Razor Hill Grunts.", completion = "I've already spoken with several orcs that have returned from the beach.  All of them told me that you were the one who saved them.\n\nYou've done a noble task today, {name}.  Lok'tar ogar!  For the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[25180] = { id = 25180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tablets of the Earth", description = "Some time ago, my brother Brann sent an urgent message from Ulduar. He said he'd found an ancient titan cache with mysterious and important relics. King Wrynn dispatched one of his fastest ships to Northrend to transport the courier and the boat should've arrived by now.\n\nI'm worried, {name}. I haven't heard anything about the courier's arrival. Would you be willing to travel to Stormwind Harbor and see if he's arrived?", sourceObjective = "Bring the Tablets of Earth to King Magni Bronzebeard in Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[25181] = { id = 25181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tablets of Fire", description = "I'm expecting the arrival of a courier traveling from Northrend. He's carrying a collection of ancient titan treasures, ones I'm hoping will shed light on my troubling visions. The shaman should've arrived on one of the recent zeppelin flights and I'm starting to get worried.\n\nHe was to meet me by the zeppelin tower southwest of Orgrimmar's gates, but I don't want to miss my audience with the warchief. Would you be willing to look for the courier and see what's delaying him?", sourceObjective = "Bring the Tablets of Fire to Seer Bahura in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[25182] = { id = 25182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill 'em All!", description = "I want to see some dead goblins, {name}! Just west of here you'll find a whole warren of those little insects burrowing into the mountain.\n\nLet's see to it that they're digging their grave.\n\nDestroy them. Lay waste to their whole grubby operation. They've sown their own demise in Bael'dun, {class}, and it is time to meet the reaper.", sourceObjective = "Kill 10 Frazzlecraz Miners at the Frazzlecraz Motherlode in Southern Barrens.", completion = "Dead? Good.\n\nLet word of this deed spread, and with it, terror.\n\nThe Horde will feel the consequences of their attack on Bael'dun, and they'll rue the day they ever crossed us, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25183] = { id = 25183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...And Bury the Rest", description = "It's not enough to kill 'em - after Bael'dun, I want to give those goblins a taste of their own.\n\nGo into Frazzlecraz's mine and arm a pile of the explosives inside.\n\nAt the entrance to the mine you should see some sort of switch or plunger. Once the explosives are armed, use the plunger to blow that place sky-high. Put the fear in 'em, {class}!", sourceObjective = "Arm 6 Frazzlecraz Explosives in the Frazzlecraz Motherlode mine.", progress = "<The plunger has a number of jury-rigged wires leading into the mine.>", completion = "<The explosives are armed and ready!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25184] = { id = 25184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Mine Cart Ride", description = "All you have to do is jump in and speak with Assistant Greely when you get to the bottom.", sourceObjective = "Use the Mine Cart to take a ride to the end of the line and then speak with Assistant Greely.", completion = "As we would say in the Tinker's Union, out of the heat-applied metallic cooking container and into the oxydizing, energetic mixture of reacting gases and solids!", sourceObjectiveStatus = "unverified-source-field" }
quests[25185] = { id = 25185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deed Is Done", description = "<You shield your eyes from the blast and the debris as the mine implodes onto itself.>\n\n<General Twinbraid will be pleased, but somehow you doubt it'll be enough to quench his thirst for vengeance.>", sourceObjective = "Return to General Twinbraid at Twinbraid's Patrol in Southern Barrens.", completion = "<Twinbraid nods as you describe the destruction of the mine, but his eyes still burn with rage.>\n\nVery nice work, {name}. I suppose there's some strategic value in depriving the Horde of those minerals, but I'd have done it anyway just to crush those little green monstrosities.", sourceObjectiveStatus = "unverified-source-field" }
quests[25186] = { id = 25186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futile Resistance", description = "{name}, I certainly don't want to deliver my report to Commander Singleton without at least a little bit of good news. We've got to wrestle control of these roads back from these Horde holdouts.\n\nFrom what we can gather, Kona Thunderwalk is the name of the ringleader. He's got a camp just north of here. A Stonetalon native, he knows these roads better than his own hide. If we can wipe him out, resistance from the west might vanish.\n\nFind and kill Kona Thunderwalk, then report to Commander Singleton!", sourceObjective = "Slay Kona Thunderwalk on the border between Stonetalon and Southern Barrens.", completion = "So our supplies aren't getting through? Hmmm. Honor's Stand just gets more and more isolated.\n\nStill, the defeat of Thunderwalk should send a signal to our foes that we mean to stay. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25187] = { id = 25187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in the Floods", description = "The recent cataclysmic events have done more than wash a few boats onto our shore, {class}.  The Southfury River has overflowed, and Durotar's entire western basin is now flooded.\n\nThere are still people out there.  I've been searching for a while, but haven't been able to find anything.  Would you mind using my telescope and taking a look for yourself?", sourceObjective = "Use Thonk's Spyglass to search for survivors in Southfury Watershed.", progress = "What have you seen?", completion = "I see... so the trick is that you need to put the LITTLE end of the spyglass up to your eye.  I'll remember that piece of information.", sourceObjectiveStatus = "unverified-source-field" }
quests[25188] = { id = 25188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watershed Patrol", description = "My post is here on the tower, {name}, and I cannot leave it.  I need someone to go out there and help the people who are still trapped in the river's overflow.\n\nCan I count on you?", sourceObjective = "Search the Southfury Watershed and help the people you saw in the spyglass.", completion = "I used that trick you taught me with the spyglass, and I watched you running around down there.  Quite impressive!\n\nHow'd you make the old woman fly, by the way?", sourceObjectiveStatus = "unverified-source-field" }
quests[25189] = { id = 25189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits Be Praised", description = "Who are you?  What happened?\n\nI was alone in my hut, meditating, when...\n\nAhh, I remember now.  The spirits cried out, and the river swept in.  I'm lucky that you found me here.  I am old, and no longer physically able to endure the elements like this.  Will you lead me out of here?", sourceObjective = "Escort Grandmatron Tekla to Raggaran.", progress = "My grandmother is still out there somewhere...", completion = "My grandmother was a powerful shaman in her day.  I thought she had lost most of her powers in her old age, but I suppose some things stay with you forever.", sourceObjectiveStatus = "unverified-source-field" }
quests[25190] = { id = 25190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raggaran's Rage", description = "The quilboar are a stain on the land that not even the river can wash away.  They told me to evacuate, but I told them that my job was not yet done.\n\nHrrrraaagh!  I hate quilboar so much!  Will you help me kill them?", sourceObjective = "Kill 4 Razormane Quilboar and 4 Razormane Scouts.", progress = "I hate quilboar!", completion = "<Raggaran appears to have calmed down a bit since your last encounter.>\n\nGood, good.  One step closer to eliminating those beady-eyed, basket-wearing, hog-nosed, two-toed...\n\n<Raggaran's anger is clearly rising again.>\n\n...hunchbacked, squealing, prickly... no-good... gnome-loving... GREEEAAAAGH!  Quilboar!", sourceObjectiveStatus = "unverified-source-field" }
quests[25191] = { id = 25191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey the Destruction", description = "I had heard of enormous seismic anomalies here in Kalimdor, but I had no inkling that the geological chaos would be so profound!\n\nI need an up-to-date survey of the destruction while I stay here to study the seismographic readings. Could you gather some data via my automated survey craft? I'll take care of all the flying.\n\nWhen the survey is complete, present the data to my colleague Horton Gimbleheart in Northwatch.", sourceObjective = "Speak with Nibb Spindlegear at Honor's Stand to survey the cataclysm's destruction.", completion = "What, what!? Can't you see we're under attack here!\n\n<Gimbleheart snatches the readouts from the survey craft, then stuffs them haphazardly into a duffel bag.>\n\nYes sure of course I'll give Nibb's findings careful study. Later. From the safety of the Eastern Kingdoms, if I have any say about it!", sourceObjectiveStatus = "unverified-source-field" }
quests[25192] = { id = 25192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raggaran's Fury", description = "I will not rest until they're defeated!  Slay them all!\n\n<Raggaran catches his breath.>\n\nTheir stinking lairs are to the north, or to the southwest!", sourceObjective = "Kill 5 Razormane Dustrunners and 5 Razormane Battleguards.", progress = "Quilboar!  Kill them!", completion = "<Again, Raggaran appears calmer.>\n\nYou've done well, stranger.\n\nI'm sorry you had to see me like that.  Thank you for killing the quilboar, but maybe you should leave before I fly into another one of my rages.", sourceObjectiveStatus = "unverified-source-field" }
quests[25193] = { id = 25193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost But Not Forgotten", description = "Today marks the anniversary of my son Kron's passing.  As long as I refused to admit it, I recognize now: Kron is not returning from his crocolisk hunt.\n\nI've been working on a project... something that will memorialize Kron's passion for the hunt.  It's a crocolisk-tooth necklace... rows and rows of teeth, suitable to be worn by only the bravest young orc.  I will place it on his grave.\n\nKron was brave, but he was not strong, like you.  Will you bring me the teeth for my necklace?", sourceObjective = "Obtain 250 Crocolisk Teeth.", progress = "Kron will be remembered.", completion = "Thank you, {race}.  I will get to work on the necklace right away.\n\nBefore Kron died, I had made this for him to wear.  I have no use for it now, but perhaps you might.", sourceObjectiveStatus = "unverified-source-field" }
quests[25194] = { id = 25194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbidden Visitors", description = "Don' worry, Zen'Taji's not in any trouble.  He just been studyin' what happens when the river overflows.\n\nYa see the big tall birds that stand on the riverbank?  Zen'Taji thinks they're in trouble.  The earthquake and the flood pushed the plainstriders over to this side of the water, but they can't fly back, and they're too scared to swim.\n\nThey'll die if they stay here.  Zen'Taji doesn't like violence, but maybe YOU can attack them and scare them over to the other side.  Yes?", sourceObjective = "Attack 3 Wayward Plainstriders until they flee toward the Barrens.", progress = "Just beat on 'em, mon.  Trust Zen'Taji, they will run.  It is no big thing.", completion = "I love all the little animals, mon.  I love the big ones, too.  I just hate to see you hurt them like that... but it's for the best.", sourceObjectiveStatus = "unverified-source-field" }
quests[25195] = { id = 25195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's the End of That Raptor", description = "Many creatures died when the water came rushin' into the valley.  The raptors, however, thrived.  They're clever predators, and they've been living off the misfortune of the other creatures.\n\nOne of the raptors is particularly cruel.  He's killing the little animals and letting them rot in the water without even eating them!  He goes by the name of Screamslash, and if we're not careful, he could seriously disrupt the balance of nature.\n\nTravel north, slay him, and give his body back to nature.", sourceObjective = "Slay the raptor called Screamslash.", progress = "The raptor has always been a quick adapter.", completion = "Something happened to Screamslash when the cataclysm hit, Zen'Taji thinks.  He wasn't always so violent and irrational.\n\nThank you for your help, {name}.  Zen'Taji gonna get back to his studying now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25196] = { id = 25196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dranosh'ar Blockade", description = "You should head north from here, {name}.  Speak with Gor the Enforcer at the Dranosh'ar Blockade.  He's been placed in charge of securing shipping lanes for Orgrimmar, and Skull Rock sits right next to his precious dock.  I'm certain he'll be interested in picking up where we left off.", sourceObjective = "Report to Gor the Enforcer at the Dranosh'ar Blockade in Durotar.", completion = "You're the one who handled the Burning Blade to the south?  I've got ears in all kinds of places, boy, and word travels fast.", sourceObjectiveStatus = "unverified-source-field" }
quests[25197] = { id = 25197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Admiral Won't Back Down", description = "What? You want to stay here to fight? Typical {class}, wanting to stay and fight off the Horde while there's still a chance to run for it.\n\nLook, if you really want to save Northwatch, you should report to Admiral Aubrey in the tower behind me. He's keeping his ships here to fight, instead of ferrying us all away like I begged him to.\n\nNow if you'll excuse me, I've got to finish packing!", sourceObjective = "Report to Admiral Aubrey at Northwatch Hold in Southern Barrens.", completion = "You've ventured all the way here from Honor's Stand? Excellent, we could use your experience here.\n\nThey may have breached the walls, but Northwatch isn't going down without a fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[25198] = { id = 25198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winnoa Pineforest", description = "While we've accomplished much here, it would be a tragedy if part of this corruption has escaped our notice.  The corridors of the Wailing Cavern stretch throughout the entire Barrens, and if another spot of wild energy has made its way to the surface...\n\nYou've done enough for me, though. I would simply ask that you let a fellow druid of mine know of what's happened here. You will find Winnoa Pineforest at the Fields of Blood, southwest of here.", sourceObjective = "Speak to Winnoa Pineforest at Vendetta Point in Southern Barrens.While we've accomplished much here, it would be a tragedy if part of this corruption has escaped our notice. The corridors of the Wailing Cavern stretch throughout the entire Barrens, and if another spot of wild energy has made its way to the surface...\n\nYou've done enough for me, though. I would simply ask that you let a fellow druid of mine know of what's happened here. You will find Winnoa Pineforest at the Fields of Blood, southwest of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25199] = { id = 25199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Orders", description = "Hey! You look like you could give us a hand!\n\nIf you're willing to help our cause, we have to get you through training.  Gnome training is brutal and rigorous, so I hope you're ready.\n\nHead over to Drill Sergeant Steamcrank and he'll walk you through what you need to know.  Make sure you follow his orders when he gives them, or else you'll never make it\n\nI'm warning you though, it's tough over there.  Come back to see me, if you make it.", sourceObjective = "Follow Drill Sergeant Steamcrank's cues and then report back to Captain Tread Sparknozzle.", progress = "Did you make it through basic training yet?  Make sure you follow Drill Sergeant's orders when he gives them.", completion = "You made it through in one piece? You have more gears then I thought, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25200] = { id = 25200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredder Shutdown", description = "That no-good Trade Prince Gallywix somehow managed to stow the whole Steamwheedle Sharks footbomb team away on the yacht. I didn't even see any of them!\n\nNow he has them doing his dirty work here at the lumber yard. {name}, you're the <guy/gal> who won the championship for us back home on Kezan. You've got to get rid of them!", sourceObjective = "Slay 8 Steamwheedle Sharks.", completion = "I can't say that I was ever much of a footbomb fan, but you're giving me an appreciation for the game!", sourceObjectiveStatus = "unverified-source-field" }
quests[25201] = { id = 25201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ultimate Footbomb Uniform", description = "Look, kid, I'm here to see to it that you've got a fighting chance at the end game. Thrall's going to need your help in the fight against the Trade Prince.\n\nGreely, Hobart, and I have a plan to put together the ultimate footbomb uniform for you so that you can win the game, but I'm going to need some things first.\n\nLucky for us, this lumber yard is sick with spare shredder parts. Now get out there and give me 110%!", sourceObjective = "Collect 8 Shredder Spare Parts.", progress = "Let's see what you have there, {name}.", completion = "Yeah, these will do nicely. You did good, kid. I'll see to it that you get the best footbomb uniform ever made.\n\nIn the meantime, you've got other bombs to drop on the Trade Prince's lackeys.", sourceObjectiveStatus = "unverified-source-field" }
quests[25202] = { id = 25202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fastest Way to His Heart", description = "Oh, girl! You're never going to guess who's out on the oil platform to the north.\n\n<Izzy shakes her head sadly at you.>\n\nChip's out there, and he's working for the Trade Prince. That cold-hearted snake dropped you like a bad habit and now he's working for the other team. I even heard he's going out with that tramp, Candy Cane!\n\nI don't know about you, but if he was my ex, I'd rip his still-beating heart out of his chest.", sourceObjective = "Rip the Still-Beating Heart from out of Chip Endale's chest.", progress = "What did you decide? Death or forgiveness?", completion = "He got just what he deserved. There, there, don't cry. You'll find someone else that'll treat you right.\n\nHere, let me take that... we wouldn't want people to think that you're crazy.", sourceObjectiveStatus = "unverified-source-field" }
quests[25203] = { id = 25203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Kind of Name is Chip, Anyway?", description = "Dude! You're never going to guess who's out on the oil platform to the north.\n\n<Ace shakes head in disbelief.>\n\nChip's out there, and he's working for the Trade Prince. That traitor's now working for the other team. But worse, I heard he's going out with your ex-girlfriend, Candy Cane!\n\nI don't know about you, but if he was going out with my ex, I'd do something about it.", sourceObjective = "Slay Chip Endale.", progress = "Are you going to do something about him? You can't just let this stand.", completion = "There's no two ways about it... he got exactly what he deserved.", sourceObjectiveStatus = "unverified-source-field" }
quests[25204] = { id = 25204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Release the Valves", description = "We have to stop Trade Prince Gallywix's oil supply and bring his machines to a grinding halt.\n\nWe're going to need you to go out to the KTC Oil Platform and release the valves to overload the coolant system. After you do that, head to the platform control panel on the platform and set it to blow.", sourceObjective = "Release Valves #1 - 4.", progress = "You have not yet released all four of the valves. The coolant to the platform is still functioning within normal operating parameters.", completion = "All of the lights and indicators on the control panel are going crazy!", sourceObjectiveStatus = "unverified-source-field" }
quests[25205] = { id = 25205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wolf and The Kodo", description = "My \"associate\" here has some plans for you that I don't agree with.  His actions are hasty, uncontrolled, and irresponsible, and you may end up paying for them with your life.\n\nBefore you work with Gor, first listen to the tale that I have to tell.  It's a moralistic story - a fable - but I believe its lesson will prove valuable.  Speak to me when you are ready.", sourceObjective = "Hear the moral of Shin Stonepillar's story.", progress = "Pay close attention to the meaning behind my words, child.", completion = "The moral of the story: hasty, lazy actions have ruinous results.  We mustn't take shortcuts... we must work for our rewards.  I've been trying to tell this story to the \"Enforcer\", but I fear his Hellscream-worshipping skull is a little bit too thick.", sourceObjectiveStatus = "unverified-source-field" }
quests[25206] = { id = 25206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignoring the Warnings", description = "Ignore the shaman, soldier.  Certain powers-that-be within the Horde demand that I keep him with me, but I assure you, that Thrall-loving farseer truly sees no farther than the borders of this hut.\n\nElementals war against one another to the west of here.  I normally wouldn't mind, but I need that land clear to secure a broader shipping route to and from the Barrens.  The elementals are normally quite strong, but they are weakened by their attacks against one another.  Use this knowledge to destroy them.", sourceObjective = "Destroy 12 Warring Elementals. You may slay either Furious Earthguards or Teeming Waterguards.", completion = "See?  The shaman's tales are nothing but that... a youngling's bedtime stories.  The new Horde takes what it wants, and doesn't waste time with such frivolity.\n\nIf you get a chance, I recommend you tell Shin... and those like him... not to waste any more of your time.", sourceObjectiveStatus = "unverified-source-field" }
quests[25207] = { id = 25207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good-bye, Sweet Oil", description = "There is single big, red button on the platform control console. Clearly if ever there were a button to cause massive explosions, that is it!", sourceObjective = "Press the Big Red Button to destroy the KTC Oil Platform.", completion = "I felt the heat from the explosions all the way over here!", sourceObjectiveStatus = "unverified-source-field" }
quests[25208] = { id = 25208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tell Silvia", description = "It seems we've found an infestation far worse than the one we expected. Cho'gall is no doubt trying to use the Gordok to gain access to the remnants of Eldre'thalas within Dire Maul, full of the forbidden powers that brought the downfall of the Shen'dralar...\n\nI am rambling. Leave me, {name}. Tell Silvia of what you've learned. Whatever is occuring in Dire Maul must be stopped.", sourceObjective = "Talk to Silvia at the Tower of Estulan.", completion = "You're back. What did Estulan say?", sourceObjectiveStatus = "unverified-source-field" }
quests[25209] = { id = 25209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Threat", description = "Within the High Wilderness to the south lay countless ancient ruins. It's there that the ancestors of the night elves fooled about with arcane magic, and it's there that the Gordunni ogres wander, searching for leftover scraps.\n\nYou'll notice the forest is completely destroyed in that area; the ogres leave only useless muck in their wake, depriving the Horde of valuable resources.\n\nGo and slay the Gordunni there, {name}. Secure the area for the Horde, and only for the Horde!", sourceObjective = "Kill 16 Gordunni Ogres in the High Wilderness.", completion = "You have proven yourself to be a trustworthy and dependable ally, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25210] = { id = 25210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Change", description = "A severe illness has fallen over the creatures of this forest. While at first I hoped it was part of nature's course, it has refused to pass.\n\nThe forest stags, normally strong and serene, have suffered the worst. Some waste away in weakness; others froth and rage dangerously. If I am to consult the spirits to learn more of this sickness, I will need the stags' antlers.", sourceObjective = "Collect 8 Infected Stag Antlers.", progress = "This is a sad task, {name}, but necessary.", completion = "I thank you, {name}. I will study the horns, but the situation has become even more dire since you left.", sourceObjectiveStatus = "unverified-source-field" }
quests[25211] = { id = 25211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Hovel", description = "Don't listen to Rharen. He's as addled as they come. It's his fault that the ale got captured!\n\nAnd what's more, I figure there's a bigger issue here than the ale being stolen. The fact that there's a bunch of orcs runnin' about Dun Algaz after all these years is ridiculous!\n\nTell you what, {class}. You head in there and be sure to drive as many orcs out of those ruins as you can. Dun Algaz isn't good for much anymore, but I'll be damned if we let them just sit in there.", sourceObjective = "Kill 5 Dragonmaw Orcs in Dun Algaz.", completion = "That'll show 'em!  Nice work!", sourceObjectiveStatus = "unverified-source-field" }
quests[25212] = { id = 25212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vent Horizon", description = "We thought that we could wait for the radiation to subside around Gnomeregan, but it doesn't appear to be getting better.\n\nIf we want to take back our city, we need to make sure it's safe for our troops to enter.\n\nTake these Radiageigatrons, hop in 'Thunderflash' here,  and toss them at the ventilation shafts outside of Gnomeregan. They'll report the radiation levels directly to me.", sourceObjective = "Use Pilot Muzzlesprock's flying machine to toss Radiageigatrons at the vents surrounding Gnomeregan.", progress = "Did you deploy all the devices?", completion = "Fantastic work!\n\nThe data I received shows the radiation levels are fully within safety range of our suits. That is excellent news!", sourceObjectiveStatus = "unverified-source-field" }
quests[25213] = { id = 25213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slave Pits", description = "Sassy's over at the Slave Pits. She's there with the orcs getting ready to execute the final play on the Trade Prince.\n\n{name}, take the footbomb uniform up the road to the southwest and find her. I know she's going to want you to lead the charge!\n\nAck, I'm starting to talk like the coach now!", sourceObjective = "Speak with Sassy Hardwrench at the Slave Pits.", completion = "I was wondering where you were!\n\nDon't worry, Hobart will get that footbomb uniform converted into the most Ultimate Footbomb Uniform ever!", sourceObjectiveStatus = "unverified-source-field" }
quests[25214] = { id = 25214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape Velocity", description = "We really don't have time to rescue those that are incompetent enough to get themselves captured over and over. Still, since I have some extra rockets leftover, this problem should be a snap.\n\nTake these single-stage booster rockets down into the Slave Pits to the north and put them on the cages.\n\nThe cage will lift off into orbit and those idiots will be freed.", sourceObjective = "Use the Single-Stage Booster Rockets to launch the cages of 8 Kezan Citizens or Goblin Survivors.", progress = "You still have have more cages to liberate from their Azerothian bonds.", completion = "Oops. Well, what goes up must eventually come down.", sourceObjectiveStatus = "unverified-source-field" }
quests[25215] = { id = 25215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Distracting Scent", description = "Predators will smell these dead naga from nearly a mile away. Soon we'll find ourselves fighting just to get in and out of the cave. Care to help me clean up?\n\nJust over the ridge to the south is Glimmerdeep Gorge. If you drag the corpses from the eastern exit of the cave over there to the gorge and cut them loose, the wildlife will pick them clean before they hit the sea floor. Just steer clear of the sharks as much as you can.", sourceObjective = "Drag 3 Dead Zin'jatar Raiders into the open water over Glimmerdeep Gorge to the south.", progress = "We are they prey to many of the creatures in these waters. We cannot let our guard down.", completion = "It shouldn't take long to cleanse the water. Thank you for your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[25216] = { id = 25216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Sambino", description = "If you're heading down the trench, I'd like you to check in one of our novice members for me.\n\nHis name is Sam, but he's likely to embellish it a bit. He doesn't really understand how members of the Earthen Ring work, but he tries hard, so we try to give him the benefit of the doubt.\n\nDon't get too wrapped up in helping him with his crazy schemes. Just make sure he's still in one piece and let me know so that I can have a little peace of mind.", sourceObjective = "Find \"Sam\" at the western end of Silver Tide Trench.", completion = "Another fan of the Great Sambino! Come all this way for an autograph perhaps? I'm far too busy to be signing anything... move along now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25217] = { id = 25217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totem Modification", description = "Okay, I'll let you in on the real work, since you're looking at me so desperately.\n\nThis rock is untapped! It's probably richer than a trade prince during a great war! I need samples. More samples. Samples from everywhere!\n\nI've modified my earth totems to drill through the sand and store samples of the rock underneath. Go find a nice spot and plant one.\n\nThe shaking and rumbling will probably attract all the cute, curious wildlife, so maybe you can make some friends while you're at it.", sourceObjective = "Plant one of Sambino's modified totems in the sand of Silver Tide Trench.", progress = "Bah! There's sand in my helmet. It itches!", completion = "Another sample. Brilliant! The rocky riches of the sea shall soon be mine!", sourceObjectiveStatus = "unverified-source-field" }
quests[25218] = { id = 25218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undersea Inflation", description = "Fine! Fine. You argued me into it. You can help.\n\nI'm leaking air worse than a zeppelin stuffed with quilboar! My air valve must have come loose somewhere in the trench.\n\nI brought spare air balloons - make yourself useful and go fill one up, will ya? And find my valve! I'll need that too.\n\nI bet the crabs snatched it up... pinchy, greedy little things.", sourceObjective = "Fill one of Sambino's Air Balloons and find his Lost Air Valve.", progress = "If only air weren't so darn floaty! Or if only those water breathing spells came with stylish helmets! Either would do nicely.", completion = "Ya know, I should have given you a weight belt so that you wouldn't just float away, air balloon and all. Lucky for me you came down here with armor and all! Hah!", sourceObjectiveStatus = "unverified-source-field" }
quests[25219] = { id = 25219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't be Shellfish", description = "I'm researching snails.\n\nYes. Snails. When you're done laughing, maybe you can help.\n\nI'm sure you noticed the gigantic shellfish across the ridge... well, I'm pretty sure there's something inside it. It has several points that can only be mouths or entrances of some kind, and I've seen those sifting snails squeezing in and out.\n\nI'm thinking that we might be able to use the snails to gain entrance ourselves. That's the theory anyway.", sourceObjective = "Collect 10 Coilshell Sifters.", progress = "I know, this isn't the most desirable work, but can you really help but be curious about that shell? It's immense. There has to be something more to it.", completion = "Thank you. Seriously. If I would have had to endure another shipwreckee laughing at me, I swear I would have gored someone.\n\nI'll let you know if I come up with anything.", sourceObjectiveStatus = "unverified-source-field" }
quests[25220] = { id = 25220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slippery Threat", description = "Been attacked by any of the eels along the ridges yet? If not, you will. They are vicious, bloodthirsty little monsters. They don't seem to show much of any preference in what they're biting.\n\nIf you're going out into the valley, I'd appreciate if you thinned their population a bit. Not everyone here is as well equipped as you - we might not come back with just scratches.", sourceObjective = "Kill 12 Spiketooth Eels.", completion = "Thank you, {class}. There are still much bigger predators we'll have to keep an eye out for, but this will at least give us a bit of peace of mind around the cave.", sourceObjectiveStatus = "unverified-source-field" }
quests[25221] = { id = 25221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rundown", description = "They're getting away!\n\nThese are the same naga that attacked the boats and carried away our friends. We cannot let them escape!\n\nTake these spears and run them down with that seahorse of yours... don't waste your time dismounting, just keep after them and kill all that you can with the spears.\n\nI will try to hunt down that Fathom-Lord. Meet me at the far end of the ledge when you're done.", sourceObjective = "Use Toshe's Hunting Spear to run down 20 fleeing Zin'jatar naga.", progress = "Our other allies are in the cave below. Things look safe from here, but it's hard to be certain.\n\nDid you do as I asked of you?", completion = "Swift work. Very impressive.\n\nThat Fathom-Lord got away... I don't see him anywhere. He's most certainly the key to finding our captured friends.\n\nI will hunt him down. He cannot stay hidden for long.", sourceObjectiveStatus = "unverified-source-field" }
quests[25222] = { id = 25222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Tide Hollow", description = "Most of the other Earthen Ring that escaped the massacre on the boats have taken shelter in a cave a short swim down from the ridge. It's tucked midway up a huge rock formation, west of Nespirah, the gigantic shell on the horizon.  I need you to make sure they're okay. There's no telling how many naga might have attacked them as well.\n\nI'm going to hunt down that Fathom-Lord. I'll send word if I find the rock he's hiding under.", sourceObjective = "Seek out Felora Firewreath in Silver Tide Hollow.", completion = "A friendly face! Welcome!\n\nVery kind of you to come check on us. We're fine. A naga scouting force did find us, but I'm pretty sure none escaped. We should be safe for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25223] = { id = 25223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial By Fire", description = "I'd love to say that with the tides turning against us in Hyjal, every recruit helps our cause and so on... but to be perfectly blunt, most of you are nothing but a burden.\n\nIf I had a copper for every peasant who got too scared when the cataclysm hit and now wishes to join our side... well, let's just say I'd be a rich woman.\n\nFortunately we have checks in place to separate the wheat from the chaff.  Go and prove yourself to the fiery instructors below.  Hopefully you'll do better than the others.", sourceObjective = "Defeat 8 Fiery Instructors.", completion = "I suppose your abilities are... suitable.  Color me impressed.", sourceObjectiveStatus = "unverified-source-field" }
quests[25224] = { id = 25224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Bloom", description = "It is customary for new recruits to be sent on a difficult or sometimes impossible task.  I was sent to obtain a black dragon's scale; last year's instructors demanded a feather from a phoenix.\n\nYour lot has it relatively easy.  Find me a handful of flame blossoms.\n\nThey grow around here in relative abundance.  Oh, right.  There will be a gigantic core hound roaming the fields to keep things interesting.  Do your best to avoid him.", sourceObjective = "Obtain 5 Flame Blossoms.", progress = "Yes, Drankloredamus?", completion = "So you managed to pass this part of the test without getting yourself eaten by Smolderos or being incinerated by the fire elementals?\n\nI suppose I should congratulate you on ascending the lowest rung of our ladder.\n\nWell... congratulations, recruit!", sourceObjectiveStatus = "unverified-source-field" }
quests[25227] = { id = 25227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thonk", description = "<Oh, sweetie, I just remembered!/Sorry if I've been mean to you.  Sometimes I get a little jealous when other women come into town> as I'm a little insecure about my appearance.;\n\nMy VERY good friend Thonk works in the guard tower on that cliff, just to the northwest of Razor Hill.  He said something about a river overflowing, lots of work to be done, and so on.  I wasn't really paying attention... I was staring into those deep brown eyes of his.\n\n<What, we can't see other people?/Thanks.>", sourceObjective = "Report to Thonk on the guard tower northwest of Razor Hill.", completion = "Gail sent you?  Did... did she say anything about me?", sourceObjectiveStatus = "unverified-source-field" }
quests[25229] = { id = 25229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Few Good Gnomes", description = "Our engineers have been working on getting our battle machines ready for our assault on Gnomeregan, but we're out of pilots!\n\nWe've developed a device called the Motivate-a-Tron, which prevents distraction from other sources and gives the gnome the courage to enlist.\n\nAfter motivating a few Gnome Citizens, lead them out to Captain Tread Sparknozzle out at Steelgrill's Depot, just south of Ironforge.\n\nOh, and be careful. The device is still a little experimental.", sourceObjective = "Recruit Gnome Citizens from Tinker Town using the Motivate-a-Tron and lead them to Captain Tread Sparknozzle at Steelgrill's Depot.", progress = "Did you find some fresh recruits?", completion = "This is the best group of potential pilots you could find?\n\nOkay, well, I'll see what I can do.  I've been known to turn even the biggest pile of gnarled gears into a smooth-runnin' fightin' machine and I expect no less with this lot.\n\nWell, I guess it's time to work!", sourceObjectiveStatus = "unverified-source-field" }
quests[25230] = { id = 25230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Illness", description = "We've found a brood of dragon whelps gathered off the road to the north, and they show the same illness as the stags.\n\nGreen dragons are not simple beasts of nature, but the very guardians of the wild. They are magical creatures, and to see them ill as well implies this is a dangerous threat.\n\nWe must stop this from spreading further through any means. Slay the infected whelps, {name}, and return to me.", sourceObjective = "Kill 10 Noxious Whelps.", completion = "These events disturb me greatly. My study of the antlers while you were gone has revealed little.\n\nWe must find some way to fix this...", sourceObjectiveStatus = "unverified-source-field" }
quests[25232] = { id = 25232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burning Blade", description = "I've been sent to investigate the presence of more Burning Blade agents here in Durotar.  To the northeast, you'll find a cave where the organization trains their new recruits.  I'm interested in what exactly they are teaching these neophytes.\n\nI only tell you this because you seem to be looking for work.  If you're interested in a little coin, sack the cave and return with their spellscrolls.\n\nThe cave is somewhat hidden: exit Razor Hill from the east, and follow the canyon's eastern ridge.", sourceObjective = "Obtain 6 Burning Blade Spellscrolls from members of the Burning Blade in Dustwind Cave.", progress = "The scrolls, {name}, the scrolls!", completion = "This is quite interesting.  These rites aren't all that different from the spells which are taught to Horde warlocks.  This merits further investigation!", sourceObjectiveStatus = "unverified-source-field" }
quests[25233] = { id = 25233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "End of the Supply Line", description = "Cho'gall's Twilight Proveditors swear a blood oath that they will get their supplies through to the front, pledging a pound of their own considerable flesh for every pound of supplies they fail to deliver. They would rather die than fail.\n\nSee to it that they do both.", sourceObjective = "Slay 4 Twilight Proveditors at Wolf's Run in Hyjal.", completion = "Well done! The chaos we sow back here will be felt up and down the chain of command.", sourceObjectiveStatus = "unverified-source-field" }
quests[25234] = { id = 25234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Rear With the Gear", description = "Prisoners of the Twilight's Hammer are forced to lug around sundries for the war effort, like common pack animals. I want those supplies, and if we can free a few poor souls from the Hammer's shadowy grip, all the better.\n\nKill the slave drivers along the road to our south and nearby slaves should make a break for it.\n\nSearch the packs they leave behind for anything valuable, and destroy anything you can't carry.", sourceObjective = "Collect 36 Twilight Supplies left behind from freed Twilight Slaves.", progress = "Have you created some havoc down there, {name}?", completion = "<Jadi kicks open one of the crates and picks up a curved dagger within. She immediately winces in pain.>\n\nAugh! Cursed - this metal is cursed - it bites!\n\n<When the dagger falls to the ground, it shatters, as if made of brittle glass.>\n\nWhat demented workmanship is this? {name}, I've never fought any foe like this before.", sourceObjectiveStatus = "unverified-source-field" }
quests[25235] = { id = 25235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulgar Vul'Gol", description = "Hail, {class}. Care to lend a hand for the people of Darkshire?\n\nThere's a huge ogre mound just down the hill there. The Splinter Fist ogres usually keep to themselves, but they've got a bad habit of attacking travelers. Just the other day I saw one drag off a poor man's horse for food... he was lucky it left him behind!\n\nThe Night Watch wants to only risk its few members in the defense of more immediate threats, me included. But if you kill some of those ogres for me, I'll pay you for your deed.", sourceObjective = "Kill 15 Splinter Fist Ogres of any kind.", progress = "If you'd rather just sit around camp and have a drink or two, that's fine too, I guess.", completion = "I saw you drop a few of them from here. Nice work.\n\nHere's your reward, on behalf of the Night Watch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25236] = { id = 25236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Down Under", description = "Our army needs water, and luckily the elements gave us plenty of that when the cataclysm hit.  The water that filled up the canyon to the southwest should do the trick.\n\nUnfortunately, the corpses of thunder lizards still sit at the bottom of the canyon, and their electrical discharges are a bit too dangerous.  I've got grunts that can lift them out of the water, but we need someone agile enough to attach the other end of the rope.  Are you my <man/woman>, {name}?", sourceObjective = "Attach a Mageweave Tether to 8 Drowned Thunder Lizards in Thunder Ridge.", completion = "The electricity was only one of the dangers.  If those carcasses rot too long under the water, that entire source becomes undrinkable.\n\nWell done, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25237] = { id = 25237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears of Stone", description = "As you witnessed, the dragon Ysondre has told us that the tears of the land can seal the portal from which this corruption stems.\n\nWeeks ago, in the glade to the west, I saw the mountain giants distraught. They raged in frustration and wept, and their tears fell upon the stones as shining crystals.\n\nThough the giants weep no more, these stonetears must be what Ysondre referred to; a source of nature's purity. We must gather them.", sourceObjective = "Collect 7 Stonetears.", progress = "The tears are among the very rocks that the giants themselves rise from. There should be loose ones near the base of these large monoliths.", completion = "Thank you once again, {name}. I will prepare these for our final task.", sourceObjectiveStatus = "unverified-source-field" }
quests[25239] = { id = 25239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Might", progress = "You seek to continue down the path of might?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[25240] = { id = 25240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Might", progress = "You seek to continue down the path of might?", completion = "You continue to prove yourself, {name}.  Accept this, not as a gift, but as a tool for the fight against the Scourge." }
quests[25241] = { id = 25241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Land, Corrupted", description = "The cliff giants of Feralas are extensions of the earth itself, {name}. When nature thrives, they are benevolent protectors and peaceful guardians.\n\nBut as the forest is tainted, so too are they.\n\nIf the corruption has spread to them, they will lash out at the wildlife and their own kind, causing great destruction. You must destroy any corrupted giants you come across.", sourceObjective = "Kill 7 Corrupted Cliff Giants.", completion = "The spirits of these guardians will return in time, {name}. You've freed them to move on in nature's cycle.\n\nNow it falls to us to make sure that cycle is free of corruption and needless suffering.", sourceObjectiveStatus = "unverified-source-field" }
quests[25242] = { id = 25242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of Might", progress = "You seek to continue down the path of might?", completion = "You are a true champion of our cause, {name}.  None can claim to be more dedicated to the struggle than you.\n\nIt is rumored that the minions of the Scourge fear you more than they do the Lich King himself.  You are might incarnate.\n\nAccept this humble gift as a reward for your many triumphs." }
quests[25243] = { id = 25243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "She Loves Me, She Loves Me NOT!", description = "Oh, sweetie! You're never going to guess who's down in the slave pits to the north.\n\n<Sassy shakes her head sadly at you.>\n\nCandy's down there, and she's working for the Trade Prince. She dropped you like a bad habit and now she's working for the other team. but it gets worse. Since you \"dealt\" with Chip, she's dating the Trade Prince!\n\nI don't know about you, but if she were my ex, I'd rip her fickle heart right out of her chest.", sourceObjective = "Rip the Fickle Heart from out of Candy Cane's chest.", progress = "What did you decide to do, hon?", completion = "I'm sure she deserved it, {name}. She should never have betrayed you like that.\n\nIt gives me the shivers to think that she might have kissed that monster, the Trade Prince!", sourceObjectiveStatus = "unverified-source-field" }
quests[25244] = { id = 25244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Kind of Name is Candy, Anyway?", description = "Can you believe that Candy Cane! You know up until you \"dealt\" with Chip, she was dating him. Now she's going out with the Trade Prince!\n\nI just can't get over the fact that she betrayed you like that with your ex. Maybe you should head down into the Slave Pits and take care of her once and for all?", sourceObjective = "Slay Candy Cane.", progress = "Are you having second thoughts?", completion = "Serves her right for stealing your man in the first place.", sourceObjectiveStatus = "unverified-source-field" }
quests[25246] = { id = 25246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, brother." }
quests[25247] = { id = 25247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, brother." }
quests[25248] = { id = 25248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, brother." }
quests[25249] = { id = 25249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, brother." }
quests[25250] = { id = 25250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Dream", description = "It is ready. Take this, {name}; a beacon of natural essence, blessed by the will of Ysondre.\n\nTo the east, on the other side of the flowing brook, is Dream Bough. There stands the Great Tree, the tallest in Feralas, a sapling of the World Tree itself. A portal to the heart of the Emerald Dream sits in its trunk, and it is this portal you must seal.\n\nThe portal will be guarded, but you must be brave. May the Earth Mother watch over you.", sourceObjective = "Use Ysondre's Tear to seal the portal at Dream Bough.", completion = "The corruption has been stemmed! The forest can begin to heal now.\n\nMay you have the blessing of the Earth Mother wherever you go, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[25251] = { id = 25251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Confrontation", description = "{name}, this is it! Thrall's down at the Gallywix Docks fighting the Trade Prince right now!\n\nYou gotta jump into your Ultimate Footbomb Uniform and get over there!", sourceObjective = "Get into the Ultimate Footbomb Uniform and then deal with Trade Prince Gallywix.", progress = "{name}, you have to go deal with the Trade Prince before it's too late!", completion = "You did it! You did it!\n\nWe're saved, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25252] = { id = 25252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rulers of Dire Maul", description = "Now that we've put the hurt on them at the ruins, it's time to attack the ogres in their own territory.\n\nThe Gordok are the \"upper class\" of the Gordunni clan, chosen to defend Dire Maul. They'll know we mean business once we start taking out their strongest members.\n\nNothing fancy here, {name}. Just get out there and crack some Gordok skulls.", sourceObjective = "Kill 6 Gordok Enforcers and 6 Gordok Ogre-Mages.", completion = "Excellent! Even these fools will soon know that to stand against the Horde means death.", sourceObjectiveStatus = "unverified-source-field" }
quests[25255] = { id = 25255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harrying the Hunters", description = "Twilight's Hammer has revealed itself as more than a mere cult. They're a war machine - a swarm of locusts moving up the mountain, devouring anything in their way.\n\nThe parts of the forest they're not setting ablaze are being scoured of life in order to feed the mortal cultists.\n\nWe've got to put a stop to the hunters canvassing Wolf's Run, not only to preserve what wildlife remains but to force the cult to march on empty stomachs. Look south of here, as well as up the road to the east.", sourceObjective = "Kill 6 Twilight Hunters at Wolf's Run in Mount Hyjal.", progress = "How goes the fight below?", completion = "Thank you, {name}. I worry that our actions here may be too little, too late, but nature always has a way of rebuilding itself that never ceases to amaze.", sourceObjectiveStatus = "unverified-source-field" }
quests[25256] = { id = 25256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sent for Help", description = "You, {race}, stop a minute.\n\nMy boss Spiketooth sent me to look for help and supplies.  You don't appear to be a merchant, but you can probably still help him out.  He's just to the southeast of here, next to the crashed cart.  Oh, and tell him I sent you... I want to make sure that he knows I'm not just slacking off over here.", sourceObjective = "Report to Spiketooth at Deadeye Shore in Durotar.", completion = "Vek'nag sent you?  Without telling you that I need wagon wheels, nails, and rations?  That idiot.", sourceObjectiveStatus = "unverified-source-field" }
quests[25257] = { id = 25257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghislania", description = "I own a couple gladiators that I put into competitions around Kalimdor.  You can see most of them chained up around here... we were lucky to rein these ones in after the cart broke down.\n\nGhislania, that naga over there... she's lost her last three fights.  She could use a tune-up, or maybe just a little bit of thrashing.  Go challenge her, I'll bet even YOU are stronger than she is.", sourceObjective = "Defeat Ghislania in combat.", completion = "I watched you fight out there.  How long you been a {class}?\n\nYou're alright, kid.", sourceObjectiveStatus = "unverified-source-field" }
quests[25258] = { id = 25258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Griswold Hanniston", description = "Griswold, chained up over there on the cliffs, is my newest gladiator.  We found him just south of here, sniffing around with Northwatch soldiers.  I had my men nab him up, and now he works for me.\n\nHe looks tough enough, but he hasn't really been battle-tested yet.  Go pick a fight with him so I can see if he's worth keeping around.", sourceObjective = "Defeat Griswold Hanniston in combat.", completion = "I'm at a crossroads now, {name}... you defeated him easily in combat, but then again, I did get him for free, and he's pretty cheap to feed.  Maybe we'll keep him around for a bit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25259] = { id = 25259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaur Icehorn", description = "I wouldn't normally keep a taunka as a captive, due to their close relationship with the Horde... but this one is a traitor, and a criminal to boot.  Exiled by his own tribe, he canoed down to Azshara and was found stealing supplies from Valormok.  He would have been put to the axe had I not been standing by, wallet in hand.\n\nGaur is my winningest gladiator, {class}.  I'll bet you 10 silver that you can't beat him.", sourceObjective = "Defeat Gaur Icehorn in combat.", completion = "Fine, here's the money... but you'd better make yourself scarce before I reconsider my policy on keeping Horde slaves.", sourceObjectiveStatus = "unverified-source-field" }
quests[25260] = { id = 25260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fizzled", description = "The flood to the southwest wiped out one of the few Burning Blade camps that still pockmark Durotar.  This one was led by a goblin named Fizzle Darkclaw, and believe me, we're better off without him.\n\nDarkclaw, however, did possess an orb that the Horde is interested in procuring.  Who knows why... I leave that to the warlocks.  All I know is that I need that orb.", sourceObjective = "Obtain Fizzle's Orb from Fizzle Darkclaw in Thunder Ridge.", progress = "Run into any trouble on the way?", completion = "I ask for an orb, and you bring half of the goblin's arm with you?  I like the way you work.\n\nTell you what... you've already given me a hand.  Allow me to return the favor.", sourceObjectiveStatus = "unverified-source-field" }
quests[25261] = { id = 25261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Margoz", description = "One of our more useful shaman, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains, just outside Orgrimmar, that shelters a large band of Burning Blade cultists.\n\nBefore you go to Skull Rock, speak with Margoz.  He is wise and his council is valued.\n\nHe is camped to the southeast, between the coast and Drygulch Ravine.\n\nFollow his advice, but whatever Margoz says, {name}, I still want you to crush those cultists!", sourceObjective = "Speak with Margoz.", completion = "Welcome, {name}.  Word reached me of your coming, and of your exploits in Durotar.\n\nYou are a {class} of growing skill and renown.\n\nStay on the pure path, and your future will be great indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[25262] = { id = 25262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skull Rock", description = "{name}.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.\n\nBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.\n\nGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.", sourceObjective = "Gather 6 Searing Collars from the cultists in Skull Rock.", progress = "Have you yet entered Skull Rock, {name}?  Do you have the Searing Collars?", completion = "Good.  Hiding within these collars is the secret behind the Burning Blade.  And I will uncover that secret...", sourceObjectiveStatus = "unverified-source-field" }
quests[25263] = { id = 25263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neeru Fireblade", description = "The Searing Collars you brought me are powerful demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.\n\nTake a searing collar to Neeru Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.\n\nYou may find Neeru in Orgrimmar in the Cleft of Shadow.", sourceObjective = "Bring an Example Collar to Neeru Fireblade in Orgrimmar.", progress = "My most humble greetings, {class}.  How might I help my {race} brother today?", completion = "Ah, and where did you get this?  Good Margoz sent you to me, did he?\n\nWell, let me take a closer look...", sourceObjectiveStatus = "unverified-source-field" }
quests[25264] = { id = 25264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ak'Zeloth", description = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.\n\nIt belongs to the Burning Blade.\n\nYour role in this tale is nearly complete, {name}.  Go to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  Pass on to him this information.", sourceObjective = "Speak with Ak'Zeloth at Far Watch Post in the Northern Barrens.", completion = "This is not news to me.  While I appreciate your efforts, the Burning Blade will have to wait.  We have other matters to which we must attend.", sourceObjectiveStatus = "unverified-source-field" }
quests[25265] = { id = 25265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory!", description = "We just can't thank you enough for all that you've done. Now we can all get off of this island before it kills us!\n\nThrall is going to want to speak with you first, {name}. I'll rocket you over there.\n\nSee you on the ship!", sourceObjective = "Speak with Thrall at the Gallywix Docks on the Lost Isles.", completion = "Lok'tar! Victory, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25266] = { id = 25266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Emissary", description = "The goblins and orcs have accomplished too much together to part ways now, {class}. I intend for the Bilgewater Cartel to become part of the Horde.\n\nI have something that I want you to deliver to the new warchief. Give this package to my Kor'kron friend on the dock at Bladefist Bay in Durotar. He will help you to get into Orgrimmar safely.\n\nSpeak with Sassy Hardwrench on the ship when you are ready to set sail.\n\nUntil we meet again. Aka'Magosh, a blessing on you and yours, {name}!", sourceObjective = "Deliver the Sealed Package to the Kor'kron Loyalist on the docks at Bladefist Bay in Durotar.", progress = "What possible business could you have in Orgrimmar, {race}?", completion = "<The orc continues on in hushed tones.>\n\nI know who sent you. Did he give you something to deliver to me?", sourceObjectiveStatus = "unverified-source-field" }
quests[25267] = { id = 25267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message for Garrosh", description = "<The Kor'kron loyalist opens the package, palming one object while reading a letter from within. As he finishes the note from Thrall, the barest hint of a fanged smile appears on his face.>\n\nYou are to take this directly to Warchief Hellscream inside Orgrimmar. Make certain that Garrosh knows that it is from Thrall.\n\nTake my battleworg. Hurry, little goblin, there is no time to waste for this message!", sourceObjective = "Deliver the SI:7 Emblem to Garrosh Hellscream at Grommash Hold in Orgrimmar.", progress = "What is this, {race}? Your kind are not allowed inside Grommash Hold.\n\nLeave before I have to teach you your place.", completion = "Thrall had you deliver this?\n\n<The Warchief takes a step back, visibly shaken.>\n\nI understand the meaning of this all too well, {race}.\n\n\n\nThis smelly thing was caught unattended in the city and seems to recognize you.\n\nI have already put others of your kind to work in Azshara. Take it with you when you leave.\n\nFrom this day forward, you and your Bilgewater Cartel will serve the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[25268] = { id = 25268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice of Goldrinn", description = "Southwest of here lies the shrine of Goldrinn, a memorial erected in honor of the ancient wolf spirit and his contribution during the War of the Ancients.\n\nOur new worgen allies have been drawn to the memory of the wolf god - go figure! - and were in the process of cleaning up the shrine.\n\nI haven't heard anything from my contact, Ian Duran, in days. Can you fly down there and find him? I've got a bad feeling that Goldrinn's shrine is in trouble...", sourceObjective = "Locate Ian Duran near the Shrine of Goldrinn in Hyjal.", completion = "You're here to rescue me, {class}? Thank you!\n\nNo, no, don't worry about the cage for now. My life isn't important. We've got to save the shrine, first.", sourceObjectiveStatus = "unverified-source-field" }
quests[25269] = { id = 25269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice of Lo'Gosh", description = "Have you heard of Lo'Gosh, the wolf ancient? In the Alliance tongue, he is known as \"Goldrinn.\"\n\nI don't need to tell you how important the wolf god has been to the Horde - his tenacity under adversity has been an inspiration to all of our disparate races.\n\nSouthwest of here, down in the valley, lies a shrine to Goldrinn. My friend Takrik Ragehowl was refurbishing the shrine when I stopped hearing from him. I fear the worst.\n\nPlease find Takrik and make sure the shrine is okay!", sourceObjective = "Locate Takrik Ragehowl near the Shrine of Goldrinn in Hyjal.", completion = "Lok'tar, {class}! Don't worry about this cage - these animals will come to fear me before long.\n\nMy first priority is to clear this filth away from my beloved shrine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25270] = { id = 25270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Howling Mad", description = "The shrine has been taken, {name}. We need the tenacity of Lo'Gosh now more than ever.\n\nThese defilers - the lice-ridden wolf-men running rampant over the shrine - dishonor the memory of the wolf god. They arrived with the Twilight's Hammer, howling with their own twisted religion. They seek to corrupt noble Lo'Gosh to fit their own warped pantheon.\n\nKill them! Kill them and bring me the tools of their worship, a kind of polluted incense. I must understand what they want with the shrine...", sourceObjective = "Acquire 6 Polluted Incense.", progress = "These animals were once men, but they've turned into mindless beasts under the influence of the Twilight's hammer. Do not hesitate to slay them all.", completion = "<Takrik examines the incense.>\n\nDisgusting. This is like the incense we burn when we wish to commune with the spirits... but it's... befouled.", sourceObjectiveStatus = "unverified-source-field" }
quests[25271] = { id = 25271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldrinn's Ferocity", description = "The beasts you see here, they're no longer my brothers from Gilneas. They've been corrupted by some kind of madness, and they've taken over the shrine.\n\nThey came when the Twilight's Hammer arrived in Hyjal, and they howl the name of some blasphemous mockery of our beloved Goldrinn. Forget about me - destroy these vandals before they continue to defile the shrine.\n\nAs you destroy them, look for the incense they carry and bring me some samples.", sourceObjective = "Acquire 6 Polluted Incense.", progress = "Worgen like myself were drawn to the story of Goldrinn, his strength and wisdom. But these vandals - they worship a different aspect of the wolf god entirely.", completion = "<Ian examines the incense.>\n\nAs I suspected. These reagents bear the marks of the Twilight's Hammer. And here, the name \"Lycanthoth.\" I believe these are used in a summoning ritual...", sourceObjectiveStatus = "unverified-source-field" }
quests[25272] = { id = 25272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lycanthoth the Corruptor", description = "The actions of these feral dogs are beginning to make sense. The Twilight's Hammer fears the power of the ancients. They do not want Lo'Gosh to return.\n\nSo they've summoned their own wolf god - a perversion of what once was. \"Lycanthoth,\" the corruptor.\n\n{name}, Lycanthoth is but a shadow of Lo'Gosh's power, but the beast must be destroyed so that the true ancient can return. Take this incense, and burn it in the Maw of Lycanthoth east of here. Slay the monstrosity and free the spirit of Lo'Gosh!", sourceObjective = "Use Lycanthoth's Incense within the Maw of Lycanthoth in Hyjal to summon and kill Lycanthoth.", progress = "Your bravery is an inspiration to others, {class}. Tell me your name.", completion = "You were brave to face down Lycanthoth, {name}. Like myself, he was a primal force of nature... but his origins were from a darker place.\n\nThose who birthed that beast reached deep into the blackness, channeling powers never intended for this world.\n\nCome, {class}. Climb onto my back, and let us show these beasts the true face of ferocity!", sourceObjectiveStatus = "unverified-source-field" }
quests[25273] = { id = 25273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lycanthoth the Corruptor", description = "I think I understand what's happening here. The Twilight's Hammer fears that the ancients may someday rise up to oppose them. They'll do anything to stop the return of Goldrinn.\n\nThis \"Lycanthoth\" is a twisted version of our beloved wolf god, summoned by the Twilight's Hammer to replace him.\n\nBah! It is but a shadow of Goldrinn's power. {name}, kill this beast so that the true ancient can return. Take this incense and burn it in the Maw of Lycanthoth east of here. Slay that beast and free Goldrinn!", sourceObjective = "Use Lycanthoth's Incense within the Maw of Lycanthoth in Hyjal to summon and kill Lycanthoth.", progress = "Your bravery is an inspiration to others, {class}. Tell me your name.", completion = "You were brave to face down Lycanthoth, {name}. Like myself, he was a primal force of nature... but his origins were from a darker place.\n\nThose who birthed that beast reached deep into the blackness, channeling powers never intended for this world.\n\nCome, {class}. Climb onto my back, and let us show these beasts the true face of ferocity!", sourceObjectiveStatus = "unverified-source-field" }
quests[25274] = { id = 25274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signed in Blood", description = "You're here at last, {name}.  Just in time as well.\n\nNews of Ragnaros' emergence has spurred a large wave of recruits to seek membership in the Twilight's Hammer.\n\nIf you're to infiltrate the cult, the time is now.  We will need recruitment papers -- signed in blood by a referring Twilight member.  Lure one of the new recruits away from the group and hit them with this blackjack.\n\nIf you're lucky, you'll be able to steal his recruitment papers.  Bring them back to me and we'll do our best to alter them.", sourceObjective = "Lure a Twilight Recruit away from the group and take his Twilight Recruitment Papers.", progress = "Did you get the papers?", completion = "Excellent.  I'll do my best to alter these documents.", sourceObjectiveStatus = "unverified-source-field" }
quests[25275] = { id = 25275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Labor Captain", description = "Your people are busy with the terraforming of Azshara. We will remake the land in the image of the Horde so that all will know that Kalimdor is ours!\n\nGo north through the city. On the far side of the Valley of Honor you will find the Orgrimmar Rear Gate. Report to Labor Captain Grabbit outside the gates, goblin.\n\nFor the Horde!!!", sourceObjective = "Report to Labor Captain Grabbit at the Orgrimmar Rear Gate in Azshara.", completion = "{name}? The {name}?!\n\n\n\nThe rumors are already flying about you. I don't know if I should be thankful or frightened that you're here. At least we don't have any volcanoes in Azshara!\n\nHonestly, I can't believe you're showing your face here... Trade Prince Gallywix has setup shop atop the mountain!", sourceObjectiveStatus = "unverified-source-field" }
quests[25276] = { id = 25276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your New Identity", description = "There.  Not my best work, but certainly not my worst.  You will be known as \"{name}damus\" among the cultists.\n\nThese papers will bump you ahead of the other recruits and allow you to speak directly to the Twilight instructors.\n\nGo to the proving grounds and show these to Condenna the Pitiless.  She's separating the wheat from the chaff.\n\nShow her what you're made of.", sourceObjective = "Speak to Condenna the Pitiless at the Training Grounds in Hyjal.", progress = "You will address me with the respect I am due, recruit.", completion = "Johnfdkdamus?  Let us hope your parents brought you into this world with more than just a ridiculous name.", sourceObjectiveStatus = "unverified-source-field" }
quests[25277] = { id = 25277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning House", description = "We are well on our way to returning the shrine to its former glory, {name}. But there is some housecleaning to take care of. On the other side of this meadow, some ogre squatters are setting up camp, led by a thick-headed chunk of ugly by the name of Gar'gol.\n\nKill Gar'gol's minions and see if we can't send him packing.", sourceObjective = "Kill any combination of 8 Hovel Brutes or Hovel Shadowcasters within Gar'gol's Hovel in Hyjal.", completion = "Hah! So you really sent some heads rolling, did you?\n\nIt was said during the War of the Ancients that Lo'Gosh fought demons for ten days solid. Hopefully you weren't fighting that long...", sourceObjectiveStatus = "unverified-source-field" }
quests[25278] = { id = 25278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning House", description = "Thanks to your efforts, we may soon be able to return this shrine to its former glory. But first we've got to secure this valley. South of here, a group of ogres led by Gar'gol has set up camp in a stinking hovel.\n\nI wouldn't characterize Gar'gol as a 'threat' so much as an enormous fleshy obstacle thrown into our path to distract us from the real danger. Nonetheless, he and his goons will have to be dealt with.\n\nKill Gar'gol's minions in Goldrinn's name!", sourceObjective = "Kill any combination of 8 Hovel Brutes or Hovel Shadowcasters within Gar'gol's Hovel in Hyjal.", completion = "You really cleared that place out, didn't you? Well done!\n\nThe night elves once told me a story about how Goldrinn fought and killed a dreadlord, even as three others clung to his flanks, burning his flesh. I wonder if you or I will ever have the strength to do the same?", sourceObjectiveStatus = "unverified-source-field" }
quests[25279] = { id = 25279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine Reclaimed", description = "Yes, {name}. I am Goldrinn, the one called \"Lo'Gosh\" in your tongue. Your persistence in the face of fear has unbound me from twilight's grasp.\n\nMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.\n\nReturn to Takrik and continue your work here in Hyjal. I will have need of you again soon.", sourceObjective = "Return to Takrik Ragehowl at the reclaimed Shrine of Goldrinn in Hyjal.", completion = "{name}, it was incredible! For a fleeting moment I saw Lo'Gosh through the trees - a creature of both fury and light. My cage collapsed and the vandals melted like wax under the kiss of his claws, their screams and howls echoing through the valley... Was that your work?", sourceObjectiveStatus = "unverified-source-field" }
quests[25280] = { id = 25280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine Reclaimed", description = "Yes {name}, I am Goldrinn. Your persistence in the face of fear has unbound me from twilight's grasp.\n\nMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.\n\nReturn to Ian and continue your work here in Hyjal. I will have need of you again soon.", sourceObjective = "Return to Ian Duran at the reclaimed Shrine of Goldrinn in Hyjal.", completion = "{name}, it was astounding! Goldrinn himself appeared to free us, his white fur bright like the summer moon. Our cages collapsed and the vandals melted like wax under the kiss of his claws. He was beautiful, {name}. Beautiful!", sourceObjectiveStatus = "unverified-source-field" }
quests[25281] = { id = 25281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pay It Forward", description = "You are now able to move about this realm more freely and without fear of drowning.\n\nThis is where our work begins.\n\nFirst, you have many allies nearby who are drowning as we speak. As I saved you, you must save them.\n\nI have enchanted the shell you brought me. Use it to rescue your friends.\n\nHurry now!", sourceObjective = "Use the Enchanted Conch Shell to rescue 6 Drowning Soldiers.", progress = "Were you able to rescue the soldiers, {race}?\n\nWe will perish without their help...", completion = "While you were away, I was able to revive some of the fallen soldiers.\n\nWe'll need every hand if we are to survive here.", sourceObjectiveStatus = "unverified-source-field" }
quests[25283] = { id = 25283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepping the Speech", description = "High Tinker Mekkatorque asked me to write a speech that he could give before the battle starts, but I can't tell which draft is good and which ones just stink.\n\nCould you try some of them out on some of the local gnome residents?  This device creates an image of Mekkatorque saying a few lines from each of my speech drafts.\n\nLet me know which one works, okay?", sourceObjective = "Use the Gnomish Playback Device in front of Ozzie Togglevolt north of Kharanos, Milli Featherwhistle at Steelgrill Depot and Tog Rustsprocket outside the Kharanos Inn. Return to Toby Ziegear when all the speeches have been given.", progress = "Hey, did you have a chance to test out my speeches?", completion = "Oh my.  Their reactions were that different?\n\nNot completely what I was expecting, but I think I have a speech that will do.\n\nJust let me find where I put it...", sourceObjectiveStatus = "unverified-source-field" }
quests[25284] = { id = 25284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Fear", description = "Our resources are limited, {class}, but that doesn't mean we can't make some trouble down below. Use the ropes here to sneak down the hillside, then slay the human prison wardens.\n\nKilling a couple scrawny guards won't turn the tide of battle, but  imagine the fear and chaos we'll reap as the humans discover the mutilated bodies...\n\n<Holgom grins a yellowed grin, his eyes glinting.>", sourceObjective = "Kill 5 Tower Wardens. Use the ropes beside Holgom to quickly move in and out of Honor's Stand.", completion = "Good, good. It'll take them many sleepless nights to figure out where we came from and where we disappeared to after the kills...", sourceObjectiveStatus = "unverified-source-field" }
quests[25285] = { id = 25285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In and Out", description = "We've gotta get these new mechano-tanks ready for the assault.  You ready to help test these bad boys out?!  Of course you are!\n\nFirst, we need to make sure that once you're in, you can get out.  In battle, if you think your tank is going to explode, get out!  I've seen many a gnome stay in 'til the bitter end... the tank blows up, and them along with it.\n\nWell, I've upgraded this tank with an ejection seat.  Try it out for me, will ya?", sourceObjective = "Test out the ejection system in the Ejector Mechano-Tank.", progress = "Those ejection systems aren't going to test themselves... though that isn't a bad idea...", completion = "Hey, look at that!  You weren't blown to bits!", sourceObjectiveStatus = "unverified-source-field" }
quests[25286] = { id = 25286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words for Delivery", description = "Here we go.  This is the speech, {name}!\n\nIt has everything to be a great battle starter: It's inspirational, has eloquent language and speaks directly to gnomes.  Never has a finer speech been written!\n\nTurn this in to Captain Tread Sparknozzle and get some transportation to High Tinker Mekkatorque!", sourceObjective = "Give the speech to Captain Tread Sparknozzle at Steelgrill Depot.\n\nProvided item:", completion = "Toby is all done with the speech?  Let me see...\n\n<Reads the speech> Pumping pistons! What a fantastic speech! I knew Toby was a good writer, but this is perhaps the best he's ever written.\n\nI think it's time to get you out to the battle.", sourceObjectiveStatus = "unverified-source-field" }
quests[25287] = { id = 25287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words for Delivery", description = "All right, soldier. Time to prove your worth!\n\nTake the speech and board the flying machine \"Thunderflash\".  It's the fastest ship to High Tinker Mekkatorque and this speech is the only thing he's waiting on before starting Operation: Gnomeregan.\n\nGo! Now!", sourceObjective = "Ride 'Thunderflash' from Steelgrill Depot to High Tinker Mekkatorque and deliver Toby's speech.", progress = "Were you here to deliver Toby Zeigear's speech?", completion = "This is the final draft, then?  Let me have a look...", sourceObjectiveStatus = "unverified-source-field" }
quests[25289] = { id = 25289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Step Forward...", description = "With the ejection system working, I think we're ready to test out movement.  This tank has an extra special feature: Automatic Evasive Maneuvers!\n\nI want you to check out the servos on the left leg, the right leg and the Automatic Evasive Maneuver system.\n\nThis is easy stuff, so it shouldn't take too long.", sourceObjective = "Test the the Scuttling Mechano-Tank's maneuverability.", progress = "I'm waiting on those test results, {name}.", completion = "Hmm... so the left leg servo was activating the right leg?  But I saw the left leg moving...\n\nEh, details.  I'll get to that later, but two out of three things worked: That isn't half bad!\n\nThanks for checking this out for me, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25291] = { id = 25291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Training", description = "You've proven you're worthy of at least participating in our most basic training.\n\nYou'll find one of our settlements east of here.  Speak to instructor Mylva there.", sourceObjective = "Speak to Instructor Mylva in Hyjal.", completion = "You think you're ready for the next step then, Johnfdkdamus?\n\nLet's see what you're capable of.", sourceObjectiveStatus = "unverified-source-field" }
quests[25292] = { id = 25292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Next of Kin", description = "<Nato pulls you aside and speaks in a whisper.>\n\n{name}, I have removed the bullet from Gann's chest, but the bubbles in his blood tell me all I need to know. His lungs are punctured, and the wound grows septic. He is not long for this world.\n\nTake this. It's the bullet that killed him. His family will want to know what became of their youngest warrior.\n\nSeek out Alto Stonespire. He is posted in Dustwallow Marsh. Go northeast, and follow the roads to Brackenwall Village.", sourceObjective = "Take the Dwarven Slug to Alto Stonespire at Brackenwall Village in Dustwallow Marsh.", progress = "Hello, {class}. You look to be caked in dust instead of mud. I take it you've ventured here from the Barrens?", completion = "<Alto clenches the bullet in his palm as you tell your story.>\n\nGann? Dead? I ... I should've known. His temper... his recklessness. I knew someday it would get the better of him.\n\nBut it sounds as though you've already gifted him with vengeance. Thank you, {name}!\n\nTurn your attention now to Dustwallow. If the Alliance finishes their cursed road through here, all your victories in the Barrens may have been for nothing.", sourceObjectiveStatus = "unverified-source-field" }
quests[25294] = { id = 25294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walking the Dog", description = "Hmmmphh.... it seems they'll let anyone in these days.\n\nVery well.  You doubtlessly became acquainted with Smolderos in the proving grounds.\n\nWell, I've been entrusted with the care of one of his pups.  Quite the little terror -- if he grows up to be anything like his father he shall serve our cause well.\n\nCollect meat from the basilisks around the area and feed them to him.", sourceObjective = "Collect and feed 5 pieces of Charred Basilisk Meat to the Spawn of Smolderos.", progress = "Well... is he fed?  I'm not taking him back unless the little monster's not hungry anymore.", completion = "Excellent.  This little pup will grow to be strong and merciless like his father.", sourceObjectiveStatus = "unverified-source-field" }
quests[25295] = { id = 25295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Press Fire", description = "Safety systems, online!  Motor functions, functioning!  Now all we need is to make sure that the guns will fire.\n\nThis shouldn't be too hard, {name}.  The mechano-tank on the hill behind us has been loaded with harmless pellets. Just fire off a couple rounds at the nearby targets and report back to me.", sourceObjective = "Test out the Shooting Mechano-Tank weapon systems on the nearby targets.", progress = "What's wrong?  Did you forget how to shoot?", completion = "Hmm... so the bullets had quite a bit of spread?\n\nTo some people that may be a problem... me, though, I see it as a blessing in disguise!\n\nOur enemies will be running all over the place, so with a bit of a spread, the tank drivers won't need to lead the target!", sourceObjectiveStatus = "unverified-source-field" }
quests[25296] = { id = 25296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gather the Intelligence", description = "It's me, {name}, Ortell!\n\nDon't look directly at the outhouse... you'll give away my position.\n\nEverything's going according to plan then?  Excellent!\n\nI'm going to need you to obtain some intelligence while you're here.  It might not seem like much to get our hands on a map or a letter, but it may mean saving a hundred lives on our side if we can anticipate our enemy's next move.", sourceObjective = "Obtain the Twilight Communique and the Hyjal Battleplans.", progress = "Did you get the documents, {name}?", completion = "Excellent job, {name}.  Or should I say: \"{name}\"damus?\n\nGive me a minute to read these.", sourceObjectiveStatus = "unverified-source-field" }
quests[25297] = { id = 25297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Mouth of Madness", description = "I know of a draught that should jolt these gibbering former slaves back to reality. Gather some stonebloom from the rocks around Gar'gol's hovel, some bitterblossom from the shores of the nearby lake, and a darkflame ember from one of the braziers at the hovel entrance. The draught won't last long, so combine the ingredients at a twilight cauldron by the entrance to the hovel.\n\nOne sip of that draught should knock some sense into the brainwashed slaves!", sourceObjective = "Gather up Stonebloom, Bitterblossom, and a Darkflame Ember.", progress = "<The cauldron burbles, filled with a disgusting liquid.>", completion = "<You dump out the current contents of the cauldron, instantly killing the surrounding plant life.>\n\n<The draught you brew in its place boils chunky and reeks of rotted cabbage. You turn your head aside and bottle it up.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25298] = { id = 25298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Your Mind, the Rest Follows", description = "<Rio said that the draught would not remain effective for long.>\n\n<You'd better hurry into the hovel and administer it to as many Twilight Servitors as you can find.>", sourceObjective = "Speak with 8 Twilight Servitors to administer the draught and rescue them.", progress = "Did the draught work?", completion = "Excellent! Let's hope the damage wasn't permanent.\n\nJudging by the poor victims still in camp here, the Twilight's Hammer really messed with their heads.", sourceObjectiveStatus = "unverified-source-field" }
quests[25299] = { id = 25299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mental Training: Speaking the Truth to Power", description = "You might think you're ready to receive the knowledge we're to impart on you.  But you are not.\n\nThink of your mind as a box inside a series of other boxes.\n\nEach step of our training will open one of those boxes, until you are ready to achieve direct communion with the elements.\n\nTake the Core of Ascension and answer all questions it asks of you, truthfully.  Failing to do so could be... fatal.", sourceObjective = "Use the Orb of Ascension and answer 10 answers correctly.", progress = "You've returned.", completion = "You've succeeded, Johnfdkdamus.  You're ready for the next step.", sourceObjectiveStatus = "unverified-source-field" }
quests[25300] = { id = 25300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Twilight", description = "The ogre clan across the lake is led by Gar'gol. I use the term loosely; Gar'gol has the intelligence of raw beef.\n\nSo far as I can tell, Gar'gol is taking orders from a magical instrument: \"The Eye of Twilight.\" He follows its commands unquestioningly.\n\nIf we can sabotage the eye, we can cause unimaginable havoc.\n\nGo to Gar'gol's hovel and seek out the Eye of Twilight near the entrance. Study it. Find a way to subvert it. Ah, marvelous chaos...", sourceObjective = "Seek out the Eye of Twilight near the entrance to Gar'gol's Hovel in Hyjal.", completion = "<You approach the Eye of Twilight. As your fingertips graze its luminescent surface, you are aware of a malignant presence peering back at you, searching your soul.>\n\n<Instinctively, you draw back.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25301] = { id = 25301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering Puppets", description = "<During your brief communion with the Eye, you felt that its power source lay deep within the hovel. You felt the weight of a powerful tome, binding together four elements.>\n\n<Mastering the Eye will require you to search the hovel for this tome.>", sourceObjective = "Locate the Twilight Apocrypha inside of Gar'gol's Hovel in Hyjal.", completion = "<A heavy tome, bound in flesh, lies open on the table.>\n\n<The language - pictographic and scrawled in rust-colored ink - is undecipherable, but notes and translations are tucked within several pages. This must be what you're looking for.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25303] = { id = 25303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementary!", description = "<You can't read the text, but diagrams seem to indicate that the devices around you should be activated in a set order.>\n\n<One passage of the Apocrypha has been translated to modern text:>\n\n   In the beginning was shadow eternal.\n   Hate blazed forth, and FIRE was born.\n   Wounds scabbed, and so begat EARTH.\n   Cries of anguish birthed howling WIND.\n   Wherein the skies wept seas of TEARS.\n      We live in the shadow,\n      The world we know\n   Built of rage, hurt, anguish and sorrow.", sourceObjective = "Activate the four nearby elemental crucibles in the correct order to take control of the Eye of Twilight.", progress = "<You pour over the Apocrypha, trying to make sense of it all.>", completion = "<Flush with the energies of the captured elementals, you stand before the Twilight Apocrypha. The pages turn of their own accord.>\n\n<Suddenly, you see what the Eye sees. It is yours to command!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25304] = { id = 25304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Sardor", description = "Our settlement on Sardor Isle was lost to the Hatecrest naga. Overwhelmed by their numbers, we fell back to the mainland. While they coveted their newly-gained sandbar, we raised New Feathermoon on the shore and amassed an even greater army.\n\nNow, the Hatecrest will be driven back into the sea. Find our Ancient of War along the shore. He will take you to the front lines, where Tambre leads the offensive.", sourceObjective = "Speak with Tambre on Sardor Isle.", completion = "These foul things will be driven back into the sea. I hope you're ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[25305] = { id = 25305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Look Back", description = "Our settlement on Sardor Isle was lost to the Hatecrest naga. Overwhelmed by their numbers, we fell back to the mainland. While they coveted their newly-gained sandbar, we raised New Feathermoon on the shore and amassed an even greater army.\n\nNow, the Hatecrest will be driven back into the sea. Speak with Sentinel Ranadae to join our forces at Sardor. Slay the naga, and make sure whichever foul snake they take orders from is killed as well.", sourceObjective = "Kill 10 Hatecrest Naga and slay their leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[25306] = { id = 25306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're In The Army Gnow!" }
quests[25308] = { id = 25308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of Discord", description = "According to the intelligence you acquired, there is major friction between the ogres and non-ogres in the cult.\n\nHigh Cultist Azennios and the ogre mage Karr'gonn are meeting at the Seat of the Chosen in an attempt to ease the conflict.\n\nThere is an outhouse like this one at the Seat of the Chosen.  Go there and put on this ogre disguise.  Find a way to kill Azennios while he's in this mission of peace.\n\nWe must exploit this division as much as we can!", sourceObjective = "Distract Karr'gonn and slay Dark Cultist Azennios at the Seat of the Chosen in Hyjal.", progress = "Is it done yet, {name}?", completion = "Excellent job, {name}!  You've outdone yourself this time.", sourceObjectiveStatus = "unverified-source-field" }
quests[25309] = { id = 25309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritual Training: Mercy is for the Weak", description = "You've made it this far.  Others haven't.\n\nGo to Doom's  Vigil, just north of here.  We've rounded up all the... failures.  I want you to help take care of them.  It'll be good for your spiritual growth.\n\nIf this cold-blooded act gives you trouble, think of it as their second chance.  Should any of them manage to kill you... well, they'll take your spot.", sourceObjective = "Slay 5 Failed Supplicants at Doom's Vigil.", progress = "Well, Hidemyaxedamus.  Is it done?", completion = "You're on the fast-track to success.  Let us hope you don't ruin your track record with such silly notions as compassion and humaneness.\n\nCome, then.  Let us discuss your future.", sourceObjectiveStatus = "unverified-source-field" }
quests[25310] = { id = 25310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Greater of Two Evils", description = "We took Darkwhisper Gorge from the demons of the Burning Legion by force.  We've held on to our territory pretty well so far, with one exception.\n\nWe recently lost the Gates of Sothann to a pit lord and his army.  We cannot allow this to stand.\n\nUse this talisman when you're near him.  You'll gain the powers of a flame ascendant temporarily.  Make it count.", sourceObjective = "Use the Talisman of Flame Ascendancy and slay Garnoth, Fist of the Legion, at the Gates of Sothann in Hyjal.", completion = "Excellent work, Beefshammichdamus.  We must show all would-be competitors that we are not ones to give up easily.", sourceObjectiveStatus = "unverified-source-field" }
quests[25311] = { id = 25311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Territory", description = "The demons of the Burning Legion think they can just walk up here and take whatever territory they want.  Sure -- the territory was previously theirs, but that's beside the point.\n\nWe'll teach them not to cross the Twilight's Hammer.\n\nHead to the Gates of Sothann and wipe out the contingent of Horrorguards that roam the area.", sourceObjective = "Slay 10 Horrorguards at the Gates of Sothann in Hyjal.", completion = "Sharp as always.  You do not disappoint me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25312] = { id = 25312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Duskwhisper", description = "<You force your own image into the Eye, manipulating it to give the ogres different orders. As you do so, you feel another presence within the Eye, probing you, seeking out a weakness. A distant being fumes with rage. You've made some enemies today!>\n\n<Your work here is done, and the ogres will be friendly to you. Return to Royce Duskwhisper at the Shrine of Goldrinn and let him know what you've accomplished.>", sourceObjective = "Return to Royce Duskwhisper at the Shrine of Goldrinn in Hyjal.", completion = "Hello, yes? What? You? Oh, you're one of the ones I sent after the Eye of Twilight, aren't you?\n\nGood work, very good. I suppose that's a valuable lesson:\n\nNever to take orders from a big purple ball.", sourceObjectiveStatus = "unverified-source-field" }
quests[25314] = { id = 25314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speech Writing for Dummies", description = "Listen, {name}.  I found out what they're doing with Jarod Shadowsong.  He's scheduled to be sacrificed by the ogres of the Twilight's Hammer as part of this year's initiation.\n\nI heard that the initiate charged with delivering the speech ahead of the sacrifice is an ogre named Okrog, but get this: you were a close second.\n\nWe need you to deliver that speech if we're to free Jarod.  Don't worry -- I'll write you some cue cards -- just make sure Okrog has an \"accident\" as he leaves the Seat of the Chosen.", sourceObjective = "Kill Okrog outside the Seat of the Chosen in Hyjal.", progress = "Well, {name}?", completion = "Excellent work, {name}.  Our plan's almost come together.", sourceObjectiveStatus = "unverified-source-field" }
quests[25315] = { id = 25315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graduation Speech", description = "You're finally ready, {name}damus.\n\nI am so proud of you and all you've accomplished.\n\nToday you will deliver a speech in front of your peers and inspire them to crush our enemies until Hyjal is nothing but a pile of ash.\n\nRemember, {name}damus.  It'll be important to read your audience's emotions and use words that best address those emotions.", sourceObjective = "Use the Initiation Podium at Doom's Vigil to successfully deliver the Graduation Speech.", progress = "Have you come to finish me off?\n\nNo... you appear to be... sane.", completion = "You.  You're clearly not with them.\n\nAn ally then?", sourceObjectiveStatus = "unverified-source-field" }
quests[25316] = { id = 25316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "As Hyjal Burns", description = "{name}!  We've heard much about you and your previous accomplishments.\n\nIt is good that you've come here just as Azeroth finds itself in a time of great need.\n\nDeathwing's minions are attacking Hyjal and seek to bring the destructive Ragnaros back into our world.\n\nAronus will take you to join Malfurion's forces in Hyjal. Lend them what help you can.", sourceObjective = "Fly to Hyjal using Aronus and speak to Ysera once you're there.", completion = "<Ysera appears to be in some sort of trance.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25317] = { id = 25317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protect the World Tree", description = "<Ysera's eyes look distant, as if not fully acknowledging you.>\n\nI feel it as well, {class}. Ragnaros has arrived.\n\nWe must defeat his minions before he can join them and lend them his strength.\n\nSeek Malfurion Stormrage at the Tranquil Grove, west of here, and aid his forces in any way you can.\n\nI must seek answers from within the Emerald Dream.  You must protect the World Tree until I return.", sourceObjective = "Speak to Malfurion Stormrage at the Tranquil Grove in Mount Hyjal.", completion = "You've arrived just in time, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25319] = { id = 25319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Twilight's Hammer", description = "Make no mistake about this, {name}.  The outcome of this war will determine the very survival of our world as we know it.\n\nThe Twilight's Hammer has become more powerful than ever with Deathwing's return.  Should they succeed in taking over the World Tree, they might strike a blow from which we will never recover.\n\nIt is time we beat back the enemy.  It is time we crushed the Twilight's Hammer.", sourceObjective = "Kill 4 Twilight Flamecallers and 10 Twilight Vanquishers.", progress = "Is it done, {name}?", completion = "You've done well, {name}.  But I fear the battle is far from over.", sourceObjectiveStatus = "unverified-source-field" }
quests[25320] = { id = 25320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captured Scout", description = "I've heard about you, {name}, and the news you brought from the south.  The battle has reached a stalemate.\n\nOne that I fear is about to be broken by the Firelord's reawakening.\n\nThat is unless we tip the scales in our favor in some way.\n\nThere is a scout that was captured by the Twilight's Hammer.  I believe she was in possession of valuable intelligence. Find her in the Twilight camp to the west.", sourceObjective = "Find Scout Larandia at the Twilight Command Post in Mount Hyjal.", completion = "Help has arrived at last!", sourceObjectiveStatus = "unverified-source-field" }
quests[25321] = { id = 25321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Captivity", description = "I'd been scouting behind enemy lines for nearly a day when they caught me.\n\nThis attack on our frontlines is not what it appears, {name}.\n\nI'll give you all the details, but first let's find a way to get me out of here.\n\nOnly the overseers carry keys to these cages.\n\nFrom what I recall, they're in the middle of the crater, in the thick of it.\n\nSee if you can get a key off of one of them.", sourceObjective = "Obtain a Twilight Overseer's Key at the Twilight Command Post in Hyjal.", progress = "The key, {name}.  Did you get it?", completion = "I am thankful, {name}.  I will deliver my findings to our people.", sourceObjectiveStatus = "unverified-source-field" }
quests[25323] = { id = 25323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flamebreaker", description = "The large elementals that besiege us are not a singular entity.\n\nThey are an amalgamation of lesser spirits bound together by the Twilight's Hammer cultists' magic.\n\nThe rebuilt flameseer's staff will give us enough power to shatter its bonds.\n\nDestroy the smaller elementals once you've broken up the more dangerous large ones.", sourceObjective = "Kill 30 Unbound Flame Spirits.", progress = "Is it done, {name}?", completion = "Well done, {name}.  This will help us turn the tide against the enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[25324] = { id = 25324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Prisoner of Interest", description = "The Twilight's Hammer wants to free Fandral Staghelm?\n\nMalfurion suspected his corruption ran deep... this just cements it.\n\nAt any rate we cannot allow our enemies to get their hands on such a powerful arch druid.\n\nI've a plan, {name}.  We will move the prisoner through the Emerald Dream.  It will be risky, but with all the cultists present here it might be the only way to guarantee our success.\n\nSpeak to Saynna Stormrunner inside the Barrow Dens to the northeast.", sourceObjective = "Speak to Captain Saynna Stormrunner at the Barrow Dens in Hyjal.", completion = "The dragon might be right.  The Twilight's Hammer has breached our security and this is our most dangerous prisoner.", sourceObjectiveStatus = "unverified-source-field" }
quests[25325] = { id = 25325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Dream", description = "Alysra's plan might be necessary, {name}.  I don't know how much longer we can hold off the cultists.\n\nFandral Staghelm is bound by powerful spells.  He won't be able to escape you, even inside the Emerald Dream.\n\nBeware, though, for all we know the nightmare has spread to this part of the world inside the dream.\n\nTake Fandral to the surface and hand him to Alysra.  Let us hope he's more secure in Moonglade than he is here.", sourceObjective = "Deliver Arch Druid Fandral Staghelm to Alysra at the entrance of the Barrow Dens in Hyjal.", progress = "Is Staghelm with you, {name}?", completion = "You did well, {name}.  I will take Fandral to Moonglade myself.\n\nHis prison will be far enough from the battlefront there.", sourceObjectiveStatus = "unverified-source-field" }
quests[25328] = { id = 25328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar'gol's Gotta Go", description = "<Kristoff cranes his neck, trying to look you in the eye.>\n\nListen, you gotta get me outta here. They're either going to eat me or turn me over to the Twilight's Hammer. Maybe both.\n\nThey've padlocked me in, and Gar'gol keeps the key in his personal treasure chest. Kill Gar'gol if you have to - but get that key!\n\n<Kristoff flails his limbs, helplessly.>", sourceObjective = "Get the Rusted Skull Key from Gar'gol's Personal Treasure Chest.", progress = "Key? Now? Please?", completion = "<Kristoff reaches down to snatch the key.>\n\nIt's about time!\n\n<He squirms in his bonds, trying to reach the padlock behind his back.>\n\n...Can I get a little help here?", sourceObjectiveStatus = "unverified-source-field" }
quests[25329] = { id = 25329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Stonemaul", description = "So the Twilight's Hammer thinks it can just raise its own army of ogres here? In the middle of Horde territory? \n\nWe'll see about that.\n\nOgres only respect one thing: strength. I want you to lead the assault on Cho'gall's sermon, {name}. Throw wide the doors of Dire Maul, leap into the arena, and cut down his attendants.", sourceObjective = "Disrupt Cho'Gall's Twilight Sermon.", completion = "We've done it! Cho'gall himself has been utterly humiliated by you. His minions are dead, the Gordok are scattered, and now all will know the might of the Horde! Lok'tar, {name}. You've more than earned your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[25330] = { id = 25330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waste of Flesh", description = "Look at these fools.  Half of them won't even make it past this trial.\n\nThey are not worthy of ascending into our inner circles.  But perhaps... perhaps they are worthy of menial service.\n\nTake this gem and utilize its power to save some of the less competent supplicants.  Those who have no chance of succeeding.  Those already on fire, preferably.", sourceObjective = "Use the Frostgale Crystal to extinguish the flames on 4 Immolated Supplicants.", progress = "Did you find suitable servants for me, Farspaladamus?", completion = "Excellent work, Bluepaddamus.  I'm having the servants you chose for me briefed on their new duties.", sourceObjectiveStatus = "unverified-source-field" }
quests[25332] = { id = 25332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Me Outta Here!", description = "<You reach up to unfasten Kristoff's bonds.>\n\nGood! Make a break for the exit, and I'll follow.\n\nIf we get separated, check back here to make sure I haven't been recaptured.", sourceObjective = "Escort Kristoff out of Gar'gol's Hovel.", completion = "Kristoff, Kristoff... Oh yes, I remember now. I recall sending him on what amounted to a suicide mission.\n\nHe survived? I suppose that means he failed.\n\nStill, you deserve at least some coin for the trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[25333] = { id = 25333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Might of the Sentinels", description = "The Twilight's Hammer? Here?\n\nThis is far more serious than I expected. We've got to put a stop to this. I don't know if I'm ready to lead such an offensive, but I'm not about to let my fears get in the way of what needs to be done!\n\nI will rally our forces from Feathermoon Stronghold. Head to Dire Maul, make your way to the arena, and disrupt Cho'gall's activities; we will launch our attack during the confusion.", sourceObjective = "Disrupt Cho'Gall's Twilight Sermon.", completion = "Welcome back from the battle! The Twilight's Hammer have been disgraced in the eyes of the Gordunni, and driven from Feralas.\n\nWe've shown the glory of the Alliance in full force today! Be proud!", sourceObjectiveStatus = "unverified-source-field" }
quests[25334] = { id = 25334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Looming Threat", description = "Can ya feel how angry the elements be? They be wantin' to attack us and consume us even as we just arrive. We need ta calm dem, but that kinda wisdom only comes from knowin' what's riling them up in da first place.\n\nCome sit with me by da fire. Let yaself get lost in da flames... let ya spirit peer into the true threat.", sourceObjective = "Speak to Farseer Gadra to enter your Spirit Trance.", progress = "Lose yaself in the dancin' flames. Come with me, deeper into Vashj'ir, so that we be knowin' the face of our enemy.", completion = "We'd all suspected da naga, but I knew nothin' of the Twilight Cult bein' beneath the waves. Somehow dey are corruptin' and pervertin' the elements, makin' demselves into dese horrors.\n\nWe goin' ta have to be fightin' both of dese threats to stand a chance of bringin' peace ta Vashj'ir. We don't have da men ta do that yet.\n\nCome, {class}, we got much ta do.", sourceObjectiveStatus = "unverified-source-field" }
quests[25336] = { id = 25336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing the Vessel", description = "Master Uzer'i's taught me in the ways of making spirit weapons of great power. I'll help you set on the path to make some, and you'll give me the chance to practice my craft.\n\nThis vessel can shrink and trap a defeated creature inside of it. We'll need the muisek of beasts first; ironfur bears and longtooth wolves. Kill them, and use the muisek vessel to shrink and capture them before their spirits can escape.", sourceObjective = "Kill 10 Ironfur Bears or Longtooth Runners, and use the Beast Muisek Vessel to shrink and capture the fallen beasts.", progress = "Did you get the beast muisek?", completion = "As my master told me...\n\nUpon a violent death, the muisek of a creature may escape and seek revenge. Shrinking the creatures, as you did, {name}, prevents the muisek from escaping. Now we may use it as we please!", sourceObjectiveStatus = "unverified-source-field" }
quests[25337] = { id = 25337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippogryph Muisek", description = "The next step is hippogryphs.\n\nAs Master Uzer'i always said, hippogryphs have been loyal companions to the night elves for many years, an' their spirits are loyal and steadfast.\n\nI don't think they'll miss a few, and I don't care if they do. We need the muisek of 10 frayfeather hippogyphs in the wilderness to the south.", sourceObjective = "Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.", progress = "Were you able to capture the hippogryphs?", completion = "Master always said \"after killing an animal, if we allowed the muisek to escape, it may take the form of an even greater creature.\" This is dangerous stuff. Thanks for helping me with my studies.", sourceObjectiveStatus = "unverified-source-field" }
quests[25338] = { id = 25338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treant Muisek", description = "The wandering forest walkers that can be found meandering through the forest are our next target, {name}. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.\n\nSoon we will be able to use this power for our own benefit.\n\nFind three wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.", sourceObjective = "Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.", progress = "Were you able to capture the wandering forest walkers?", completion = "Thank you, {name}. This is my first time working with treant muisek...", sourceObjectiveStatus = "unverified-source-field" }
quests[25339] = { id = 25339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance on the Northspring", description = "In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...\n\nI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.\n\nEven now, I can still hear their cries echoing...\n\nI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.\n\nThe Northspring harpies can be found to the west of here. {name}, get my revenge.", sourceObjective = "Kill 6 Northspring Harpies and 6 Northspring Windcallers.", completion = "Thank you, {name}. You have put an old tauren's mind at peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[25340] = { id = 25340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Heart", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.\n\nI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.\n\nImagine her surprise when it is not her kin calling her, but her death.", sourceObjective = "Slay Edana Hatetalon and obtain Edana's Dark Heart.", progress = "The hate that Edana spreads across the land must be stopped.", completion = "Now I know that Edana is truly dead. This heart, I will keep it in memory of what you did here for me, {name}. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25341] = { id = 25341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Orb", description = "While you're down there cracking skulls...\n\nI've gotten reports that make me think these ogres may be more than the usual lumbering threat. The Warlocks among them have been seen carrying orbs, possibly items of empowerment.\n\nIt would be easy to dismiss them as crude trinkets, but I need to make sure we're not surprised. Bring me back one of these orbs.", sourceObjective = "Collect a Gordunni Orb from a Gordunni Warlock.", progress = "Do you have the orb?", completion = "Well done. Let me have a look at this.", sourceObjectiveStatus = "unverified-source-field" }
quests[25342] = { id = 25342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talk to Swar'jan", description = "We're lucky and unlucky here, grunt. Lucky that I had you bother to bring this back, and unlucky that my suspicions turned out to hold water. This thing's full of corrupted stench.\n\nIt's far too new to be something fished out of the ruins, either. Someone is supplying these ogres, and we need to know who before this becomes a situation.\n\nGet that filthy thing upstairs to Swar'jan, the warlock on top of the guard tower. He's good for a few ideas; I'd listen to his suggestions, if I were you.", sourceObjective = "Deliver the Gordunni Orb to Swar'jan in Stonemaul Hold.", progress = "Yes?", completion = "What've you got for me here? You said the Gordunni had this?\n\nDisgusting...", sourceObjectiveStatus = "unverified-source-field" }
quests[25344] = { id = 25344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Abduction", description = "There's no way the Gordunni made these. They're being supplied. Someone is giving them gifts of power, and we need to find out who.\n\nThe upper-class Gordok that guard Dire Maul will know more about this. Orhan is no doubt having you thin their numbers, but I'll need one alive.\n\nTake the orb back. It's similar to a Soulstone, so I've made some...adjustments. Hold it up in front of a weakened Gordok ogre, and once you've captured him, bring it back here.", sourceObjective = "Use the Modified Soulstone to capture a Gordok ogre.", progress = "Well?", completion = "Ahh, I can feel the whelp in there. Let's get him out and ask him some questions...", sourceObjectiveStatus = "unverified-source-field" }
quests[25345] = { id = 25345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faerie Dragon Muisek", description = "{name}, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.\n\nHere is the muisek, {name}. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.", sourceObjective = "Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons.", progress = "Were you able to capture the muisek of the faerie dragons?", completion = "Thank you, {name}. Now the spiritual powers of the faerie dragon will be available to us.\n\nI hope you willing to perform another task for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25346] = { id = 25346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mountain Giant Muisek", description = "The mountain giants left the mountains to aid the night elves when the Burning Legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.\n\nI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek.", sourceObjective = "Kill 7 Mountain Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants.", progress = "Were you able to capture the mountain giants?", completion = "Just imagine the possibilities of what we now possess, {name}. Along with the materials that you have collected, I will be able to forever trap the muisek of these creatures into whatever I wish.", sourceObjectiveStatus = "unverified-source-field" }
quests[25349] = { id = 25349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Sisters", description = "I have heard of your battle against the corrupted dragons, {name}, and I thank you for your courage... but I have disturbing news.\n\nThe dryads of the forest, though allies of the Night Elves, have always passed us by in peace. But they have become cruel and twisted, attacking any who wander the eastern wilds.\n\nI fear for the safety of the refugees here, {name}. Please, put a stop to these twisted dryads.", sourceObjective = "Kill 7 Corrupted Dryads.", completion = "I thank you, {name}, but the tale of your hunt troubles me. There should not be so many.\n\nThe sickness is still spreading...", sourceObjectiveStatus = "unverified-source-field" }
quests[25350] = { id = 25350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Apprentice", description = "If you have a moment, {class}...\n\nOne of the students I was teaching has gone to explore the darkmist ruins to the south by himself. I warned him that it was too dangerous, but he was too excited to listen.  I had spoken with him earlier about an amulet that is concealed within those ruins.  Now, I fear that he may have run off in search of it, because of me...\n\nEstulan has forbidden us to pursue him. If you go there, could you please look for him?", sourceObjective = "Look for the Lost Apprentice in the Darkmist Ruins.", completion = "<The apprentice's body is cold. He has been dead for a while.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25352] = { id = 25352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweeping the Shelf", description = "Wonderful work in the hovel, {name}. I prayed at the shrine while you were away, and in my visions, Goldrinn was watching you closely.\n\nBut we've been on the defensive too long: it's time to foil the Twilight's Hammer directly.\n\nFly up to the Lightning Ledge and disrupt their operation. Kill the stormcallers and the monstrosities they're preparing to unleash!", sourceObjective = "Slay 8 Twilight Stormcallers and 5 Howling Riftdwellers.", completion = "You should've seen the battle from here! Bodies were falling off of the cliff! Spectacular!", sourceObjectiveStatus = "unverified-source-field" }
quests[25353] = { id = 25353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning in a Bottle", description = "When I prayed at the shrine, Goldrinn granted me another vision. I saw you standing astride the Lightning Ledge, with lightning in your hands. Goldrinn seems to feel that this is of the utmost importance, but I don't understand what the ancient has planned...\n\n{name}, go to the Lightning Ledge. Twilight's Hammer has been running experiments with something called a \"Lightning Channel.\" Investigate these channels, then use this totem to summon the Spirit of Goldrinn and see what he has in mind...", sourceObjective = "Collect a Charged Condenser Jar from a Twilight Lightning Channel.", progress = "We meet again, {class}. You carve a path of fear and confusion in your wake.", completion = "So, it is true! You indeed carry lightning in your hands.\n\nYou are the chosen one, {name}. You will be my champion, and carry my vengeance to realms where I cannot tread...", sourceObjectiveStatus = "unverified-source-field" }
quests[25354] = { id = 25354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweeping the Shelf", description = "The shrine is secure, the ogres in disarray. Enough. The time has come to go on the offensive.\n\nSomething sinister is underway above us, on the Lightning Ledge. It is time to unleash the fury of the ancients!\n\nFly up to the Lightning Ledge and demolish the Twilight's Hammer there. Crush them, {name}, slay their creations and hurl their bodies from the mountainside!", sourceObjective = "Slay 8 Twilight Stormcallers and 5 Howling Riftdwellers.", progress = "How goes the fight? I need not tell you how uneasy it makes me to have the Hammer's agents lurking above our heads.", completion = "Impressive, {name}. Very impressive.\n\nYou embody all of the strength of the wolf ancient, and possess the wisdom to use your powers well. I salute you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25355] = { id = 25355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning in a Bottle", description = "Lo'Gosh granted me a vision while you were in the hovel, {name}. I saw you striding across the Lightning Ledge, with lightning bolts in your hand. The vision was powerful: Lo'Gosh feels this is of utmost importance. We must not fail the ancient.\n\nUpon the Lightning Ledge, Twilight's Hammer has been experimenting with devices they call \"Lightning Channels.\"\n\nInvestigate one of these channels, then use this totem to summon the Spirit of Lo'Gosh and learn what the ancient is planning...", sourceObjective = "Collect a Charged Condenser Jar from a Twilight Lightning Channel.", progress = "We meet again, {class}. You fight well! You carve a path of fear and confusion in your wake.", completion = "So, it is true! You indeed carry lightning in your hands.\n\nYou are the chosen one, {name}. You will be my champion, and carry my vengeance to realms where I cannot tread...", sourceObjectiveStatus = "unverified-source-field" }
quests[25356] = { id = 25356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Summit", description = "We are staging a relief effort at Westreach Summit for all of Thousand Needles. Shyn will lend you my wind rider to safely get you there. Speak with Kanati Greycloud when you land.\n\nYou must go quickly if lives are to be saved!", sourceObjective = "Borrow a wind rider from Shyn and speak with Kanati Greycloud at Westreach Summit in Thousand Needles.", completion = "Jawn sent you? Good! We need your help, now!", sourceObjectiveStatus = "unverified-source-field" }
quests[25357] = { id = 25357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buy Us Some Time", description = "So many good men have been lost today. Without you, that number would be even higher.\n\nYou have our gratitude.\n\nIf what the shaman says is true, then there is no time to spare. The naga are scouring these waters looking for survivors.\n\nWe are not yet ready to fight. You must buy us time to make preparations. Find the naga that hunt us and delay their efforts.", sourceObjective = "Slay 8 Zin'jatar Raiders.", progress = "Have you given the naga something to think about, {class}?", completion = "Let's hope your efforts prove to be enough of a diversion...", sourceObjectiveStatus = "unverified-source-field" }
quests[25358] = { id = 25358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nerve Tonic", description = "How am I feelin', you ask?\n\nWell, after bein' yanked from the deck of our ship by a giant sea monster and then left to drown in the sea... not so good!\n\nMy nerves are gettin' the best of me, to be honest.\n\nIf you could round up some of the supplies that are sure to be floatin' around the nearby wrecks, I could likely whip up somethin' that'll take the edge off...", sourceObjective = "Mack wants you to collect 5 Sunken Cargo in Kelp'thar Forest.", progress = "Were ya able to grab some supplies, {race}?", completion = "I trust we both know what's been going on inside these crates...\n\nThat's right... ferrrmenntation! Here y'are. My personal secret recipe.\n\nYou wouldn't get this from any other guy!", sourceObjectiveStatus = "unverified-source-field" }
quests[25359] = { id = 25359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toshe's Vengeance", description = "You met Toshe back in Damplight Cavern, didn't you? He followed some of the fleeing naga to a set of ruins to the east and then sent for help.\n\nFind Toshe at the ruins as soon as you can. If you find out anything about what the naga want, please let us know.", sourceObjective = "Speak to Toshe Chaosrender at the Ruins of Thelserai Temple.", completion = "I remember you. You were there when they attacked us back in the cave.\n\nGood to have you with me, {class}. Ready for a little vengeance?", sourceObjectiveStatus = "unverified-source-field" }
quests[25360] = { id = 25360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crabby Patrons", description = "These crabs are not friendly. Not. Friendly.\n\nSam's endless drilling is riling them up. I know from experience that there's no stopping Sam, so let's look into the other side of things, shall we?", sourceObjective = "Kill 10 Green Sand Crabs.", progress = "Careful. They pinch.", completion = "Does everything down here only come in jumbo size? Oooh! That's a thought. Maybe there are some hunky sea goblins around here somewhere.\n\nThanks, by the way.", sourceObjectiveStatus = "unverified-source-field" }
quests[25361] = { id = 25361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Cloak's Sheen", description = "Well met, {class}. I've traveled with my companions down to Feralas on a mission for our Orgrimmar masters.\n\nMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with the gorgeous wings I want are west of Camp Mojache.", sourceObjective = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.", progress = "The sprite darters can be dangerous critters when provoked. Be careful when dealing with them, {class}. And be even more careful of any night elves in the area. The pestering fools tend to hold up in the forests also.\n\nWhen you've gotten enough of the wings, let me know, I'll be sure to reward you well!", completion = "Wonderful, {class}! These will do nicely. There are enough here to make a cloak for Korrin, and possibly even more! Thank you.\n\nI hope the trip wasn't too dangerous? The area of Feralas is not known for being forgiving, but you've obviously done well enough.\n\nThank you again, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25362] = { id = 25362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Discovery", description = "The Grimtotem clan! Those gutless traitors are still lurking around here, eh...\n\nYou have to go back, {class}. Go back and bring me their horns... piles of them if you can. The Grimtotem are not to be trifled with or underestimated. Go back and slay them; let the rivers in Feralas run red with their dark blood.", sourceObjective = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.", progress = "Take my words seriously, {class}, the Grimtotem clan is evil. If you've found their whereabouts, then it's up to you to return and strike the first blow against their clan... before they can come into our own lands and raze our own villages, or pilfer our lands.", completion = "Traitors to the Horde and traitors to their own people...\n\nI guess they're not all bad. They'll make fine drinking flasks.", sourceObjectiveStatus = "unverified-source-field" }
quests[25363] = { id = 25363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Woodpaw", description = "The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.\n\nThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.\n\nGo!", sourceObjective = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.", progress = "We drive them back, and yet they still attack!  Someone or something must be driving them into a frenzy... oh, you have returned, eh {name}?  Do you have the manes I require for the bounty to be met?", completion = "This is proof of a good start, {name}.  Your skills as a soldier are to be commended.\n\nYou are not the only one I ask that task of.  Many before you have fought them, and in times past, our efforts have kept them at bay.  Recently though, their attempts to push northward into our area of influence have increased dramatically.  Their attacks have also become more savage... almost as if they were desperate.\n\nI have a plan though, {name}, that might settle things once and for all against them...", sourceObjectiveStatus = "unverified-source-field" }
quests[25364] = { id = 25364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Strike", description = "Gnolls are unfortunately as resilient as they are brutish and stupid. I have driven back the gnolls time after time from our camp, and it is only our chieftain's mercy that prevents them from being wiped out entirely.\n\nOver the years, it has fallen into a dance of strength and dominance. When their numbers surge and they threaten the camp, the alphas, the strongest gnolls, must be slain.\n\nThis will drive them back into the forest, and leave us is peace until they forget their lessons.", sourceObjective = "Kill 5 Woodpaw Alphas.", completion = "You've done as I have asked, and for that I salute you.  Take this small reward as compensation for your efforts, {name}.\n\nWith their numbers thinned and their leaders slain, the gnolls will think twice about storming the camp.  This doesn't conclude the issue at hand, however...\n\nThere must be some reason why the gnolls have been whipped into such a frenzied state.  Before they have a chance to regroup, I want to find out what is causing it.", sourceObjectiveStatus = "unverified-source-field" }
quests[25365] = { id = 25365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Woodpaw Investigation", description = "Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity.  If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.\n\nI want you to head back to the Woodpaw and find anything that might resemble their battle plans.  They have to have something; their attacks have been too coordinated to be done without them.  Find them, and return to me when you have them.", sourceObjective = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.", completion = "Examining the map reveals it to be the battle plans that Hadoken Swiftstrider wants.  Numerous arrows that perhaps represent troop movements are drawn on the map, though most seem to be headed toward the south rather than to the north where Camp Mojache lies.\n\nAnother section of the map has a picture of what you think is a large insect of some kind, with various tick marks under it.  From the looks of the gnolls, it perhaps represents their losses against the unknown bugs...", sourceObjectiveStatus = "unverified-source-field" }
quests[25366] = { id = 25366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle Plans", description = "With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.", sourceObjective = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.", progress = "Welcome back {name} - were you able to find some tangible evidence as to the plans of the gnolls?", completion = "Ah, this is exactly what we needed.  While I am not so skilled at ciphering what most of the scrawling on this map is, I've seen enough battle plans in my day to understand what is happening with the gnolls.  It looks like they are currently fighting a two front war.  One is with us... but it seems that their main energy has been against a foe to their south.\n\nThere's more at hand here than meets the eye.  Perhaps it is time to figure out who this other foe they face really is.", sourceObjectiveStatus = "unverified-source-field" }
quests[25367] = { id = 25367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash Infestation", description = "From what scouting we have managed to muster, we believe that the foe south of the gnolls is an insect-like race.  Frankly, it is irrelevant whether or not they're sentient.  If they are driving the gnolls to frenzy against us, then they are as big of a threat - if not more - than the gnolls.\n\nDive deep into where these Zukk'ash insects dwell; it is known as the Writhing Deep.  Thin their numbers and report back to me what you find, bringing back their carapaces as evidence of your handiwork.", sourceObjective = "Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas.", progress = "How goes the hunt, {name}?  Are you here to report your success?", completion = "Well done, {class}.  Though the extensiveness of the Zukk'ash presence will not be thwarted with anything less than a full-scale invasion, you have bought us some time so we can devise a proper strategy.\n\nI will be sure to have these carapaces analyzed; we'll need to learn everything about them before we deal with what has unfortunately turned into a much larger issue than we had anticipated.", sourceObjectiveStatus = "unverified-source-field" }
quests[25368] = { id = 25368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verinias the Twisted", description = "The other spirits and I are bound here by a cruel demon named Verinias. He is our captor, a twisted, mindless beast who devours our souls over milennia.\n\nThe lure of the souls and arcane magic you've brought me should let you draw him out. Take this condensed essence to the dead tree at the far north of the ruins. Use it to lure Verinias and slay him, that I may finally be free...", sourceObjective = "Defeat Verinias the Twisted.", completion = "I'm free...finally! Oh, it feels so good to be free...\n\nOh, you saw, didn't you?", sourceObjectiveStatus = "unverified-source-field" }
quests[25369] = { id = 25369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinglasher", description = "In surveying the Writhing Deep, one of our scouts reported seeing a giant insect - much larger than the other insects spotted - wandering about the twisted terrain.  Not only is it larger, it also seems to secrete some sort of aura that the other insects don't.  We've given it a name - Stinglasher.\n\nThe innards of this beast would be invaluable to study as we figure out the best way to deal with this new threat.  Cut out its secretion glands and bring it back to me immediately!", sourceObjective = "Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas.", progress = "Have you managed to bring down Stinglasher yet?", completion = "Impressive, {class}... most impressive!  If Stinglasher is indeed one of their strongest creatures, the study of the beast will prove to be quite valuable in time.  It's now my charge to make sure we defend ourselves long enough to take advantage of it.\n\nPlease accept this coin bounty as a token of the entire camp's thanks, {name}.  Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[25370] = { id = 25370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inciting the Elements", description = "This is no mere natural occurrence, {name}.  There must be a twilight presence behind our lines that we haven't accounted for.\n\nIt's possible that whoever is instigating the elemental disturbance is using foul magic to hide themselves from our sight.\n\nSeek the aid of the faerie dragons that roam near the World Tree; they can see through any of our enemy's illusions.\n\nFeed them the juniper berries that grow nearby to gain their trust.", sourceObjective = "Feed Juniper Berries to the Faerie Dragons and slay 4 Twilight Inciters.", progress = "Back already, {name}?", completion = "You've done well, {name}.  We cannot allow the Twilight's Hammer spies this close to the world tree!", sourceObjectiveStatus = "unverified-source-field" }
quests[25371] = { id = 25371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abyssal Ride", description = "If you are going to be making it anywhere in this kelp forest, we need to get you a reliable mount. I think I've come up with a better plan than the sea turtle, and it's not far.\n\nTie off a lure at the rope just west of us, and then mount the seahorse that it will attract.\n\nBe warned, you may need to work hard to break the beast.", sourceObjective = "Lure and subdue an Abyssal Seahorse.", progress = "The grace of these creatures is astounding. They will make the perfect mounts.", completion = "Amazing! You look exhausted. She must have really made you work for it.\n\nLife should be a lot easier down here going forward with a mount that swift at your beckoning. Congratulations, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25372] = { id = 25372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aessina's Miracle", description = "<The finger-like branches of one of Nordu's burning limbs part, revealing an untouched, glimmering seed.>\n\nThis is the Heart of the Forest. The seed of life.\n\nTake this to your Arch Druid at Aessina's Grove - Hamuul Runetotem will know how to invoke its power. I promise you, the wilderness spirit will be silent no longer. New life will bloom from the ashes of old.\n\nThank you, {race}. My time is done.", sourceObjective = "Take the Heart of the Forest to Hamuul Runetotem at the Grove of Aessina in Mount Hyjal.", progress = "I am at my wit's end, {name}! Aessina is silent.\n\nHave you found something? What is this?", completion = "This is the key, {name}! With the seedlings you collected for me earlier, the animals you've saved from around Hyjal, and the Heart of the Forest you've just discovered, we can rejuvenate this land right from under the feet of Twilight's Hammer. Imagine their astonishment to see their work undone, as life triumphs over chaos...\n\nI will begin the ceremony at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[25373] = { id = 25373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hilltop Threat", description = "I am proud of Mojache's reputation as a safe haven in the wilds of Feralas, but the camp faces many threats. The Gordunni ogres gather nearby in the northern foothills, claiming their territory and despoiling the wildlife.\n\nWith the arrival of our brothers and sisters seeking shelter, I cannot let them linger any more. Go north and drive the ogres out.", sourceObjective = "Kill 5 Gordunni Hillguards.", completion = "I thank you, {name}, but there is more work to be done to keep the camp safe. Listen further.", sourceObjectiveStatus = "unverified-source-field" }
quests[25374] = { id = 25374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasquatch Sighting", description = "You may have seen this with your own eyes, but my longrunners have reported something disturbing to me. The gordunni in the hills have captured an enormous sasquatch from the wilds.\n\nI don't know how long it's been held, but ogres are not ones for hobbies. I fear they plan to unleash the tortured beast on Camp Mojache.\n\nReturn to the deepest corner of the Gordunni Outpost and slay the sasquatch, {name}.", sourceObjective = "Kill Bigfist.", completion = "I will be able to rest easy now, {name}. You've saved our camp from a terrible menace.", sourceObjectiveStatus = "unverified-source-field" }
quests[25375] = { id = 25375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming The Tamers", description = "The gordunni are not known to tame animals. If they're learning, this is cause for alarm. While the sasquatch they've tamed may be the major threat to our camp, the gordunni who captured him should be dealt with as well. If left, they may simply capture another.\n\nKill the gordunni tamers, and make sure the ogres know their efforts will not be tolerated!", sourceObjective = "Kill 6 Gordunni Tamers.", completion = "Good, good. Let's hope the ogres are at least smart enough to realize we're sending a message!", sourceObjectiveStatus = "unverified-source-field" }
quests[25377] = { id = 25377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde's Hoard", description = "It is unclear what manner of creature scrawled the seemingly random markings on this piece of parchment, but upon close inspection, some of the obscure shapes begin to look like landmarks.\n\nScanning the sea floor, you think you recognize a few points of reference, one being a nearby sunken ship. If your guess is correct, there appears to be treasure of some kind near the wreck.\n\nYou cannot help but wonder what the scaly, serpentine figure on the map might represent....", sourceObjective = "You must defeat Akasha to obtain the Horde Chest Key which you must then use to open the Sunken Horde Chest.", progress = "This slightly encrusted lock might still be functional.", completion = "You've discovered lost treasure!\n\nYour mind reels at the thought of what else might be hidden in the depths of the sea.", sourceObjectiveStatus = "unverified-source-field" }
quests[25378] = { id = 25378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Call", description = "The dragons of nature... Heed her call, {name}. Do not linger here. Her request for your aid is both a great honor and an omen of terrible danger.\n\nThe place she spoke of is called the Emerald Summit. A path off the main road through the Lower Wilds leads up one of the high stone plateaus; you will find a small shrine at the top.\n\nAll of Feralas may rest upon your shoulders. May the Earth Mother watch over you.", sourceObjective = "Speak with Ysondre at the Emerald Summit in the Lower Wilds.", completion = "You've come.\n\nI am ashamed to ask this of you, {class}, but I've ran from him long enough. Taerar must be stopped.", sourceObjectiveStatus = "unverified-source-field" }
quests[25379] = { id = 25379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taerar's Fall", description = "Emeriss and Lethon are gone. It's only us left now. I can hide from this no longer. All I did while a part of that brood...all the suffering I've caused...must be repaid today.\n\nI am still weak, {name}. I cannot assume my true form even if I dare try. But I will still stand beside you in battle.\n\nIf you are prepared, I will call Taerar to us. He will be unable to resist the temptation of revisiting corruption upon me.", sourceObjective = "Defeat Taerar.", completion = "It is done.\n\nThis land that has suffered so much can rest now.", sourceObjectiveStatus = "unverified-source-field" }
quests[25381] = { id = 25381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Fire With ... Anything", description = "The inferno raging up ahead marks the front line between us and the forces of the Fire Lord. The fire elementals unleashed here are unlike any I've ever encountered.\n\nCan you help us stem the tide of destruction? Slay the raging firestorms... before they engulf Aessina's Grove and erase all hope of someday reclaiming this mountain!", sourceObjective = "Slay 10 Raging Firestorms within the Inferno.", completion = "Thank you, {name}. You've given us the opportunity to try to reclaim the upper hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[25382] = { id = 25382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupting the Rituals", description = "The firestorms up ahead are unbound elementals in the purest form - something I didn't think could exist outside their own plane. Only very skilled summoners could unleash something like this.\n\n{name}, head into the Inferno and seek out Twilight Inferno Lords. They've got to be summoning in reinforcements as we speak. Silence them... For good!", sourceObjective = "Slay 6 Twilight Inferno Lords within the Inferno.", progress = "Tell me... have you found the fiends responsible for this?", completion = "Dead? Good!\n\nBut it seems there's still so much to be done... fires to quench... and the soil to heal...\n\nI hope you'll stay close and help us reclaim Hyjal!", sourceObjectiveStatus = "unverified-source-field" }
quests[25383] = { id = 25383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Farewell", description = "With that, I am the only one left.\n\nEven if I choose to remain in this world, I cannot rejoin the green flight. But this victory gives me hope. Perhaps, in time, I can find peace in a simple life among mortals.\n\nYou must return to your people. Tell them that the dragons of nightmare are gone, and will no longer threaten these lands.", sourceObjective = "Speak to Chief Spirithorn in Camp Mojache.", completion = "You are truly blessed by the Earth Mother, {name}, to have the honor of fighting with the guardians of nature, and to also survive it.\n\nKnow that you have kept safe every living soul in this camp, and possibly this entire forest. Take these gifts with my deepest thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[25384] = { id = 25384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raw Materials", description = "Thank you, {class}. We owe you our lives.\n\nBut if we're ever to see the surface again, we'll have to fight our way out of here. That means I'm going to need to craft some weapons and armor.\n\nBefore you found me, I saw a soldier eaten by one of those orca up there.\n\nI'll wager that if you cut a few of them open, you'll find plenty of scrap metal for me to work with.\n\nIf you don't want to swim up to them, I bet you could lure one down to you with some entrails...You will be able to choose one of these rewards:", sourceObjective = "Samir wants you to collect 3 Rent Scrap Metal from Frenzied Orca in the Kelp Forest.\n\nYou can lure an orca using Pincer Entrails from Clacksnap Pincers.", sourceObjectiveStatus = "unverified-source-field" }
quests[25385] = { id = 25385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save the Wee Animals", description = "Help us, {class}! The forest is aflame, and the wee animals can't find their way out. They can't fight for themselves, with their teeny-tiny little teeth and their soft furry paws! They're fluffy and sweet.\n\nThey have wet little noses!\n\nIf you don't save them, I don't want to even THINK about it.\n\n<She slaps her palms over her eyes.>\n\nI'm not thinking!", sourceObjective = "Go into the Inferno and rescue any combination of 10 Panicked Bunnies or Terrified Squirrels.", progress = "Did you save the wee animals? And their wee little friends?", completion = "Squueeeee!\n\nDid the nice Mr. {class} pull you from the flames, little friend? You're safe now!\n\nHooray!", sourceObjectiveStatus = "unverified-source-field" }
quests[25386] = { id = 25386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Stonemaul Hold", description = "You must send word of what has happened here, {name}. To the south is Stonemaul Hold. There, our allies have gathered the few ogres of the horde to fight against those despoiling these forests.\n\nSpeak with Orhan Ogreblade. She leads the Stonemaul clan here, and will need to know of all that has occured. And be wary, lest some of this corruption remain...", sourceObjective = "Speak with Orhan Ogreblade in Stonemaul Hold.", completion = "You've been tussling with drakes, eh?\n\nI like it. We need someone who can pull their own weight around here. Are you ready to fight for the Horde?", sourceObjectiveStatus = "unverified-source-field" }
quests[25387] = { id = 25387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Camp Mojache", description = "You've done a hell of a job here, {name}. With the Twilight's Hammer shamed and the Gordunni left bleeding and broken, we'll be able to set our sights on the true battle with the Alliance here.\n\nIt'll take time to build our forces enough to match the night elves infesting this place. I'm sending you ahead to Camp Mojache to the east; they've got problems of their own, and we can't let any Horde territory fall here.\n\nLok'tar!", sourceObjective = "Speak with Chief Spirithorn in Camp Mojache.", completion = "I am thankful you've come, {class}. Our camp is beset by many perils, and yet we must tend to those fleeing the devastation of the cataclysm.\n\nIf there is to be any refuge here, you must help us.", sourceObjectiveStatus = "unverified-source-field" }
quests[25388] = { id = 25388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crate of Crab Meat", description = "This crate, labeled 'Crab Meat', seems to have fallen from a recently sunken cargo ship.\n\nAdarrah would surely welcome such a find, considering the ordeal she's had to endure.", sourceObjective = "Take the Crate of Crab Meat to Adarrah in Smuggler's Scar.", progress = "What have you got there, {name}?", completion = "Why, {name}! What a surprise!\n\nIf anyone ever calls your character into question you be sure to send them my way.\n\nI'll tell anyone who'll listen that you really helped me out in a pinch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25389] = { id = 25389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste For Tail", description = "It could be days before we're ready to make our way to the surface, and to be honest, I'm already beginning to get hungry.\n\nI hate to be picky, but when it comes to seafood, I'm afraid there are very few things I can stomach.\n\nIf you come across any lobster types, I would happily pay you what coin I have with me for their tails.", sourceObjective = "Adarrah wants you to bring her 4 Clacksnap Tails.", progress = "Oh, please tell me you were able to find me some food, {class}.", completion = "Oh, my!\n\nThat's some of the biggest, juiciest tail I've ever seen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25390] = { id = 25390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Girl's Best Friend", description = "Let's just get it out in the open. I'm no stranger to love, {name}.\n\nOver the years, if there's one thing I've learned, it's that love's tangible treasures last longer than the flames of passion.\n\nI've managed to collect my fair share of these gifts - gemstones, rings, necklaces, and the like, and I carry them with me wherever I go.\n\nAt least I used to...\n\nWhen I was swept from the ship, my valuables were scattered across the sea. Help me recover them and I promise to make it worth your trouble.", sourceObjective = "Adarrah wants you to recover 6 Adarrah's Keepsakes.", progress = "Well, {race}?\n\nWere you able to recover my valuables?", completion = "Oh, you've found them! I was sure they were lost forever...\n\nHere you are, {name}. I hope this is ample payment.", sourceObjectiveStatus = "unverified-source-field" }
quests[25391] = { id = 25391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Spirit", description = "Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.", sourceObjective = "Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.", completion = "As promised, you have your choice, {name}. The muisek of the creatures has been forever sealed into the power of these weapons.\n\nYou may now wield their energy as your own. Use it well.", sourceObjectiveStatus = "unverified-source-field" }
quests[25392] = { id = 25392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, Deer!", description = "Do you speak deer? It's all in the nose.\n\n<She points to her nose.>\n\nThe does have fled the fires, but their little fawns - Some of them are still trapped in the burning and the hurt!\n\nGo back into the Inferno and escort three injured fawns back here to their mothers right here beside me.\n\nPlease save the little fawns, or I'll give you the big eyes!\n\n<Her eyes grow big and dewy.>", sourceObjective = "Rescue three Injured Fawns from The Inferno and escort them back to Mylune at the Grove of Aessina.", progress = "Hurry! I can smell the smoke!", completion = "Oh yay! Happy little deer!\n\nNow they can grow up and have ADVENTURES.\n\nYou're swell.", sourceObjectiveStatus = "unverified-source-field" }
quests[25393] = { id = 25393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Gnomeregan", description = "Momentarily, the multi-phased assault upon Gnomeregan will begin and Mekgineer Thermaplugg and his men will be brought to justice!  Too long has Thermaplugg festered in the depths of our home, defended by a corrupt and irradiated army.\n\nThe assault begins in but a moment! Be ready recruit, this fight will not be for the faint-hearted.", sourceObjective = "Help King Mekkatorque with the assault on Gnomeregan.", completion = "Curses! We had to fall back. But Thermaplugg's lost, and he knows it... he's only bought himself time. We hold the surface, and when the radiation clears we'll assault and recapture Gnomeregan with a force twice this size.", sourceObjectiveStatus = "unverified-source-field" }
quests[25394] = { id = 25394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than Illness", description = "I've discovered a brood of dragon whelps gathered off the road to the north with a similar affliction. Green dragons are sacred custodians of nature. The fact that this disease is capable of spreading to them is cause for great alarm.\n\nWe must stop this from spreading further through any means. Slay the infected whelps, {name}, and return to me.", sourceObjective = "Kill 10 Noxious Whelps.", completion = "This development worries me greatly. This has happened before...", sourceObjectiveStatus = "unverified-source-field" }
quests[25395] = { id = 25395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stolen Keg", description = "You've got to help us, <lad/lass>. We were tasked with escorting a precious cargo to our fellow dwarves...a keg full of the finest ale you can get out here!\n\nUnfortunately, bird-brain over here fell asleep on the job! Those blasted orcs took our keg, and hauled it up into Dun Algaz where they're hiding.\n\nThis can't stand! Now, while I stay here and try to convince this idiot that it was his fault, I'd like you to go in there and get our keg back. For Khaz Modan!", sourceObjective = "Retrieve the Mountaineer's Ale from Dun Algaz.", progress = "Do you have it? Is the poor thing intact?", completion = "Thank the Makers! It's downright pristine. Those orcs couldn't figure out the tap-lock, it seems...and couldn't hack through the mastercraft work of Ironforge's keg-crafters with their crude weapons!", sourceObjectiveStatus = "unverified-source-field" }
quests[25396] = { id = 25396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tears of Stone", description = "As you witnessed, the dragon Ysondre has told us that the tears of the land can seal the portal from which this corruption stems.\n\nHer words ring true; in the glade to the west, I have seen the mountain giants distraught. They raged in frustration and wept, and their tears fell upon the stones as shining crystals.\n\nThough the giants weep no more, these stonetears must be what Ysondre referred to. We must gather them.", sourceObjective = "Collect 7 Stonetears.", progress = "The tears are among the very rocks that the giants themselves rise from. There should be loose ones near the base of these large monoliths.", completion = "The mountain giants are precious allies of our race. We must stop this corruption before it claims any more creatures of the forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[25397] = { id = 25397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Land, Corrupted", description = "The cliff giants of Feralas are extensions of the earth itself, {name}. When nature thrives, they are benevolent protectors and peaceful guardians.\n\nBut as the forest is tainted, so too are they.\n\nShould they be corrupted by this malady, they will lash out in violence against trees, wildlife, and the very boulders they were shaped from.\n\nBe wary in your tasks. Should you find any corrupted giants, destroy them, for the sake of those still spared.", sourceObjective = "Kill 6 Corrupted Cliff Giants.", completion = "The spirits of these guardians will return in time, {name}. You've freed them to move on in nature's cycle.\n\nNow it falls to us to make sure that cycle is free of corruption and needless suffering.", sourceObjectiveStatus = "unverified-source-field" }
quests[25398] = { id = 25398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Dream", description = "It is ready. Take this, {name}; a beacon of natural essence, blessed by the will of Ysondre.\n\nTo the north, on the other side of the flowing brook, is Dream Bough. There stands the Great Tree, the tallest in Feralas, a sapling of the very World Tree. A portal to the heart of the Emerald Dream sits in its trunk, and it is this portal you must seal.\n\nThe portal will be guarded, but you must be brave.", sourceObjective = "Use Ysondre's Tear to seal the portal at Dream Bough.", completion = "Your bravery has seen us through! The Emerald Nightmare has been shut out from this land.\n\nThe fate of the dragon Taerar worries me...but there is much work still to be done. I cannot afford to dwell on it.", sourceObjectiveStatus = "unverified-source-field" }
quests[25399] = { id = 25399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatecrest Forces", description = "The Hatecrest are fighting fiercely! Their leader is a priority, but we need to kill as many of them as we can.\n\nGo ahead of me, I'll meet you on the battlefield. Show them no mercy!", sourceObjective = "Kill 10 Hatecrest Naga.", completion = "Your valor was mentioned in my briefings, {name}. I commend you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25400] = { id = 25400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Threat", description = "Estulan, the Highborne up in the tower, is reclusive. I haven't been able to speak to him very much. He has, however, told me that the ruins of the High Wilderness to the south are full of Gordunni ogres.\n\nThe ogres are not only a threat, they're destroying any forest and wildlife nearby. Estulan has also warned me of what might happen if they discover any artifacts of Highborne power among the ruins...\n\nHead south, {name}, and slay any Gordunni you find!", sourceObjective = "Kill 16 Gordunni ogres in the High Wilderness.", completion = "It sounds like there were more than we thought! Thank you for your brave work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25401] = { id = 25401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordunni Orb", description = "In addition to clearing out the ogres...\n\nEstulan mentioned something else about the ogres. He said the ogre warlocks may have some sort of orb, or other item of power\n\nHe was terse about it, but seemed upset...he said there was \"no way they could be Highborne\", so I think he wants to know just where they got them. Bring me back one of these orbs.", sourceObjective = "Collect a Gordunni Orb from a Gordunni Warlock.", progress = "Do you have the orb?", completion = "Is that it? Let me see here...", sourceObjectiveStatus = "unverified-source-field" }
quests[25402] = { id = 25402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Estulan's Examination", description = "He's right. I haven't been among the night elves long, but I can tell these markings are completely unlike any kaldorei decorations...\n\nEstulan needs to see this. Take this up the tower to him. He may be surly, but don't be dissuaded; once he sees the orb, he'll realize it's an important issue.", sourceObjective = "Deliver the Gordunni Orb to Estulan.", progress = "What is that you're holding?", completion = "Ahh, the orb I mentioned before. A decent reason to disturb me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25403] = { id = 25403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Abduction", description = "This is neither a crude ogre trinket, nor an ancient relic made by my kind. Its specific construction is new to me...and this fact disturbs me greatly.\n\nThe wolf-girl will be sending you to Dire Maul soon, to fight the Gordok elite. They are the leaders of the Gordunni, and would know who is supplying these.\n\nTake the orb back, I've cast a few enchantments on it. Hold it up in front of a weakened Gordok ogre, and once you've captured him, bring it back here.", sourceObjective = "Use the Modified Soulstone to capture a Gordok ogre.", completion = "Ah, you've brought him. Now I merely have to suffer the fate of speaking to him.", sourceObjectiveStatus = "unverified-source-field" }
quests[25404] = { id = 25404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You're Not Against Us...", description = "South of here you'll find a solitary tower, known as \"Blackhorn's Penance.\" Upon it is bound a demon: Tyrus Blackhorn.\n\nYou may think me mad for turning to an old foe for help, but Blackhorn was once a mortal, and I can't imagine he wants to watch Twilight's Hammer triumph.\n\nSpeak with Blackhorn, and see if you can convince him to help us in our fight. He may yet redeem himself.\n\n...Just don't set him free!", sourceObjective = "Speak with Tyrus Blackhorn and convince him to help in the fight against the Twilight's Hammer.", progress = "You were sent here to talk, {race}. So. Talk.", completion = "Very well, {race}. I will help you mortals, even from within my bonds.\n\nBut don't sicken me by claiming it's my redemption. I do this for my own ends.", sourceObjectiveStatus = "unverified-source-field" }
quests[25405] = { id = 25405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rest For the Weary", description = "You have done well, {race}, but there is much more to do and I grow weary.\n\nI have expended a great deal of energy sending a distress message to Earthen Ring leadership, pleading for their help.\n\nI must rest if I am to be of further use to us here.\n\nSpeak to the leader of the men you've saved and do what you can to help them prepare for battle.\n\nThe naga are scouring the waters for us. It is but a matter of time before they return - and they will surely come in even greater force.", sourceObjective = "Speak with Captain Taylor.", completion = "I hear you, {race}.\n\nI understand the urgency, but these men are in no condition to fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[25406] = { id = 25406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordok Guards", description = "With the nearby ogres dealt with, we should take the offensive and press our attack into their territory.\n\nThe Gordok ogres are the head of the Gordunni clan, ruling them from the ruins now called Dire Maul. They are stronger than the lesser Gordunni, but I have no doubt you can handle them, {name}. They won't know what hit them.", sourceObjective = "Kill 6 Gordok Enforcers and 6 Gordok Ogre-Mages.", completion = "Wonderful! Everything's going according to plan. Lady Shandris will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[25407] = { id = 25407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Wisps", description = "The Sentinels make up the bulk of our forces here, but a well-rounded night elf army requires more than just night elves. The creatures of this forest, our ancestral home, have protected us for centuries. We simply need to rally them.\n\nTake this whistle. Our allies know this sound, and you'll be using it to recall them.\n\nBefore you start gathering creatures, I'd like you to recall a few of our wisps, just for practice. You can find them just outside the fortress, among the trees.", sourceObjective = "Use Tessina's Whistle to recall 3 Feathermoon Wisps.", completion = "Wisps have always lived in harmony with night elves, and we depend on them for many things. These little guys you sent back, for example, will be helping us with some new construction and repairs.\n\nReady for more?", sourceObjectiveStatus = "unverified-source-field" }
quests[25408] = { id = 25408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of Their Demise", description = "We will decimate the Twilight's Hammer by corrupting and subverting them. \n\nSeeing that you have no intention of releasing me from my bonds, I require you to collect some reagents for me. My own demonic essence has corrupted the plant life around my shrine here. I need you to harvest some bileberries from the wailing weeds that surround this tower.\n\nMy little pets will attempt to harvest YOU in return. Try not to let them agitate one another.", sourceObjective = "Collect 8 Bileberries.", progress = "Has the local flora been giving you a hard time?\n\n<Blackhorn grins disturbingly.>", completion = "Very good. Please crush the berries into a pulpy liquid. That's quite an aroma isn't it?\n\nNow now, don't gag. It's beneath you.", sourceObjectiveStatus = "unverified-source-field" }
quests[25409] = { id = 25409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Hippogryphs", description = "Hippogryphs are majestic creatures. Some say they were created by Cenarius himself as a gift for the night elves. They're wary of other races, but they're intelligent enough to recognize a friend of a friend.\n\nI need more hippogryphs here so we can begin training some of our newer archers to ride them. Take the whistle again and rally the Frayfeather hippogyphs in the grove just south of the Tower of Estulan.", sourceObjective = "Use Tessina's Whistle to rally 10 Frayfeather Hippogryphs.", completion = "A properly trained squadron of hippogryph riders can take on nearly any opposing force. Feathermoon Stronghold will be much safer with these noble beasts on our side.", sourceObjectiveStatus = "unverified-source-field" }
quests[25410] = { id = 25410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forces of Nature: Treants", description = "Some people think treants are good for little more than fetching drinks in a war. Most of them haven't seen an entire defensive line scattered by what they thought was cover.\n\nAnd have you ever seen a peon try to chop one down and get surprised? I was in tears...\n\nAt any rate, they're immensely valuable allies. You'll find some wandering just outside  the Tower of Estulan and more in forest to the east, just southeast of Dire Maul. Be on the lookout for the Horde!", sourceObjective = "Use Tessina's Whistle to rally 6 Wandering Forest Walkers.", completion = "They may not look it, but some treants grow to be ancient protectors. We could use a few more of those around here...", sourceObjectiveStatus = "unverified-source-field" }
quests[25411] = { id = 25411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Master", description = "The potion you created is vile enough to wake the dead. Which is its intended purpose.\n\nSlay a Twilight Inferno Lord and force the brew down his throat. He will revive, if only briefly, and be completely under your dominance.\n\nSpeak with him and learn the true name of the fire elemental he is channeling into the world to burn down your precious forest.", sourceObjective = "Use the Bottled Bileberry Brew on the corpse of a Twilight Inferno Lord, then speak with him.", progress = "<The wavering corpse is animated briefly by foul magic.>\n\n<It doesn't acknowledge your presence.>", completion = "<The wretched creature before you speaks in a wavering voice, its body broken but briefly animated by Blackhorn's vile potion.>\n\nYes, master?", sourceObjectiveStatus = "unverified-source-field" }
quests[25412] = { id = 25412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Name Never Spoken", description = "We called upon the fury and flame of the One, my former master.\n\nThe Inferno is by His design.\n\nHis true name is never uttered, it holds His power.\n\nEach of us was told but a piece. Each piece engraved on a firestone.\n\nThe One's true name is here, in the Inferno. Seek the three stones...", sourceObjective = "Assemble the true name by examining the three Firestones.", completion = "Yes, yes! Show me the runes you discovered.\n\n\"Vol'talo Thol'embaar.\" That's the name of your real enemy.\n\nPresumably you're dealing with one of Ragnaros's generals, sent here to scorch the mountainside and pave the way for his conquest.\n\nI will show you how to crush him.", sourceObjectiveStatus = "unverified-source-field" }
quests[25413] = { id = 25413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Change of Plans", description = "Alright, kid. Slight change of plans...\n\nI think I've figured out a way to finish off that monster and you're going to assist me.\n\nThe way I see it, you owe me until my work is done here, and I ain't leaving without that artifact.\n\nFirst I need you to search those old wrecks for some good rope and a serviceable harpoon.\n\nThen... well, I'll fill you in on the rest later.", sourceObjective = "Get the Rusty Harpoon and 3 Coils of Rope.", sourceObjectiveStatus = "unverified-source-field" }
quests[25419] = { id = 25419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady La-La's Medallion", description = "Dozens of crude gold links make up this heavy chain.\n\nDangling from the center link is an opalescent fragment of what must have once been a large shell-shaped medallion.\n\nYou wonder if the other fragments might be nearby, and if the medallion might be reassembled into its original state.You will be able to choose one of these rewards:", sourceObjective = "Collect the 5 Medallion Fragments from Gilblin Collectors and combine them to create Lady La-La's Medallion.", sourceObjectiveStatus = "unverified-source-field" }
quests[25420] = { id = 25420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Obstacles", description = "I've studied the gate here for years, trying to find a way of entry that wouldn't disturb any of the ancient architecture just behind it. It figures a few overgrown earthquakes decided to muck the whole thing up! But what's done is done, and the entrance to Uldum is revealed.\n\nI wasn't expecting anything to come out of the ruins before we went in, though. A whole mess of golems are running amok in the valley now, let loose from inside. Someone needs to clean them up if we're gonna get in there!", sourceObjective = "Destroy 6 Sandstone Golems.", completion = "Good work, {class}. We're that much closer to the secrets of Uldum.", sourceObjectiveStatus = "unverified-source-field" }
quests[25421] = { id = 25421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grand Tablet", description = "At the bottom of the chest, you find a large tablet. Made of a material resembling stone, but completely smooth and flawless, it is covered in strange writing.\n\nWhile some resembles the writing on the walls, other scripts appear completely different. Gunstan would probably like to see this.", sourceObjective = "Take the Grand Tablet to Gunstan.", progress = "You're back! What have you found?", completion = "This is amazing. These hieroglyphs are undoubtedly titan, but the markings below it...\n\nIf I had to hope, this is the same passage written over and over again in an entire assortment of ancient languages. We might be able to use this to decipher the hieroglyphs! If the antechamber was covered in them as you say, who knows what else we'll learn.\n\nI'd like to grant you a fine reward, {name}. We've made the find of the century!", sourceObjectiveStatus = "unverified-source-field" }
quests[25422] = { id = 25422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkmist Legacy", description = "I am chained to this place...it takes so much effort just to speak to you. I can barely maintain this shape.\n\nI could help you, but please, help me pull myself together first. Once I'm more focused on this plane, I should be able to do it...\n\nIf I could just leave this tomb, the soil itself outside is full of ancient arcane deposits, laying forgotten for centuries. Could you bring me some?", sourceObjective = "Collect 6 piles of Glowing Soil.", progress = "Do you have the soil? I'm having trouble staying together...hurry...", completion = "Thank you! Thank you...\n\nI feel much better. With just a bit more...", sourceObjectiveStatus = "unverified-source-field" }
quests[25423] = { id = 25423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Suffering", description = "You must be careful when you venture forth. Other spirits are bound to this place, malevolvent and hateful ones. They've all suffered so much.\n\nNone of what they used to be remains, only suffering and a will to live. We will need that will to summon the overlord that keeps me bound here. Please, gather the essence of the spirits, and bring it back to me.", sourceObjective = "Collect 6 Soul Essences.", progress = "Have you gathered it?", completion = "You can feel their anguish, can't you?\n\nMy poor friends. At least we can use you to fix things...", sourceObjectiveStatus = "unverified-source-field" }
quests[25424] = { id = 25424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Alysra", description = "I thank you for freeing me, {name}.  I will tell our allies of my findings.\n\nI suggest that you return to the emerald dragon that sent you.\n\nThe Twilight's Hammer does not just seek to gain territory with this particular attack.  They're also after a prisoner.\n\nFandral Staghelm is being held in the Barrow Dens.  The attack doubles as a distraction to free him.  To what end, I cannot tell.  Perhaps our dragon ally can shed some light on this.", sourceObjective = "Return to Alysra at the Ruins of Lar'donir in Hyjal.", completion = "This development is troubling, {name}.  We must act swiftly.", sourceObjectiveStatus = "unverified-source-field" }
quests[25426] = { id = 25426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War on the Woodpaw", description = "The first of Shandris's direct orders is to deal with the Woodpaw gnolls here. They've been spreading too far, too fast, and are becoming a threat to both the forest and our war effort.\n\nThey know we're here. After we took this camp, we've been leading covert strikes against them. It's time to make a major blow; bring back ten of their manes, and we'll be ready for the next phase.", sourceObjective = "Collect 10 Woodpaw Gnoll Manes.", progress = "The manes aren't just for trophies. If there's to be slaughter, we may as well not let it be a total waste.", completion = "Excellent work, {name}. I didn't think those gnolls would give you much trouble.", sourceObjectiveStatus = "unverified-source-field" }
quests[25427] = { id = 25427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Strike", description = "Never underestimate a threat. These gnolls may seem like simple brutes, but there's animal cunning even among them.\n\nThe gnolls run as a pack, and every pack has Alphas: The biggest, strongest, and most ruthless members that claw their way to dominance. They're the ones giving orders, so they're the ones we're going to slay now.\n\nThey reside mostly around the Woodpaw Den, pushing the others around. Get out there and push harder.", sourceObjective = "Kill 5 Woodpaw Alphas.", completion = "Perfect. Any gnolls left will be simple prey, lost in the woods.\n\nHeh...here, soldier, take your reward before I get distracted. We've got other threats to deal with.", sourceObjectiveStatus = "unverified-source-field" }
quests[25428] = { id = 25428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Heart of Flame", description = "Now you will use our newfound knowledge to pull Thol'embaar into the mortal plane like a babe screaming from the womb. Then you will crush him.\n\nThe ritual is simple: take this charred branch, tap it on the ground three times, and utter his name aloud.\n\nYou must call him from within the heart of the Inferno. Destroy him, and bring his black heart back to me.", sourceObjective = "Use the Charred Branch within The Inferno to Summon Thol'embaar. Kill him and take the Black Heart of Thol'embaar.", progress = "Tell me! Have you fought Thol'embaar yet?\n\nI am living vicariously through you, {race}. Do not disappoint!", completion = "There it is! Such a trophy! Born in the fires of another plane...\n\nGo ahead, {race}. Crush it. Crush his charcoal heart in your hands and let the winds scatter the ashes... yes, yes.", sourceObjectiveStatus = "unverified-source-field" }
quests[25429] = { id = 25429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash Infestation", description = "With the gnolls out of the way, we're ready to take care of other foes. Our scouts have discovered what appears to be a hive nearby, extending deep beneath the ground.\n\nThe insects of the hive are large and ferocious, and most likely pose an even greater threat than the gnolls. I want you to proceed to the hive with caution. Cut down a good portion of the bugs and bring back their carapaces for further study.", sourceObjective = "Collect 20 Zukk'ash Carapaces.", progress = "How goes the hunt, {name}?  Are you here to report your success?", completion = "These are silithid after all...I wasn't sure, having never seen one in person. Gilneas had its problems, but at least we didn't have these monstrosities running around!", sourceObjectiveStatus = "unverified-source-field" }
quests[25430] = { id = 25430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Allies", description = "The druids of Hyjal are not the only ones sworn to defend this land.  The emerald dragons have once again become a powerful ally to our cause.\n\nSpeak to Alysra at the Ruins of Lar'donir, to the north, and see what you can do to help.", sourceObjective = "Speak to Alysra at the Ruins of Lar'donir in Mount Hyjal.", completion = "My duties are here, viewing the enemy's movement from above, commanding our armies where they're needed.\n\nYour aid would be most welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[25431] = { id = 25431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stinglasher", description = "Most of the insects we've seen wandering the hive have been enormous enough, but my scouts reported an especially huge one. It's supposedly a massive wasp, and it seemed to be directing the workers on the surface.\n\nI don't know much about these things, but if they're starting to wander beyond that pit in the ground, we need to put a stop to it. Kill this giant wasp and return to me.", sourceObjective = "Kill Stinglasher in the Writhing Deep.", completion = "Well done, {name}! You're proving very valuable to securing this area for the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[25432] = { id = 25432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Not \"Ogre\" Yet", description = "We dealt the Gordunni ogres a large blow at Dire Maul, but we haven't quite finished the job. My scouts have reported a group of them amassed in the hills to the north, gathering for some reason.\n\nIt's possible they're interested in the Horde settlement nearby, but I don't want to take any chances. Scout the area, kill any ogres you come across, and report back.", sourceObjective = "Kill 5 Gordunni Hillguards.", completion = "It's good to see you back. We've learned more about the ogre situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[25433] = { id = 25433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasquatch Sighting", description = "You may have seen it yourself, but other scouts have discovered an enormous beast being held by the ogres. Reports say it looks like a sasquatch, but if it is, it's the biggest ever seen in Feralas.\n\nThe ogres are most likely trying to teach it to obey them. While that's almost comical, I'm not going to sit by and let them train that thing to roll over at their command. Return to the hills and slay it.", sourceObjective = "Kill Bigfist.", completion = "Well done once again, {name}. Yet another threat removed from Feralas.", sourceObjectiveStatus = "unverified-source-field" }
quests[25434] = { id = 25434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming The Tamers", description = "The sasquatch may be a larger threat, but we also need to wipe out the ogres. The Gordunni have been a nuisance to us for too long, and Lady Shandris wants them completely gone.  Let's hope these are the last ones.\n\nKill the Gordunni tamers that keep the beast chained, and make sure they know the price of their meddling.", sourceObjective = "Kill 6 Gordunni Tamers.", completion = "Good work, and good riddance. I hope we never have to see another ogre here again!", sourceObjectiveStatus = "unverified-source-field" }
quests[25435] = { id = 25435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pressure is Mounting", description = "G'day, <laddie/lassie>.\n\nThe name's Rendel.\n\nSeems ol' Moanah and I got here in the nick of time, eh?\n\nErunak wasn't kiddin' when he said it was life or death!\n\nWhile he's tryin' to find us a safe place to hole up, I'm gunna take a stab at securin' you a critter to ride.\n\nNow, I may not be up on all the ins an' outs of life in the sea, but it looked to me like them naga know how to get around down here.\n\nYou round up a few widgets for a bridle and I'll work up an enchantment.", sourceObjective = "Collect 3 Shark Sinews from Ravenous Threshers and 2 Sharpened Crab Claws from Sabreclaw Skitterers.\n\nRavenous Threshers can also be summoned to you by using Crab Entrails.", sourceObjectiveStatus = "unverified-source-field" }
quests[25436] = { id = 25436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiteful Sisters", description = "Something truly disturbing has occured. While on patrol, several of my scouts were ambushed by dryads.\n\nThe dryads are close allies of the night elves and guardians of the forest. I assumed they were just frightened by the sight of worgen, but the sentinels I sent out afterwards were also attacked.\n\nWhatever is going on, I don't like it. I want you to go investigate as well. If even the dryads have been corrupted...put them to the sword.", sourceObjective = "Kill 8 Corrupted Dryads.", completion = "I didn't want to scare you, but this is a grave situation. If the portal at Dream Bough was sealed, and the corruption is still spreading...", sourceObjectiveStatus = "unverified-source-field" }
quests[25437] = { id = 25437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Call", description = "A dragon of the emerald dream... what have you gotten yourself involved in, {name}?\n\nI wouldn't keep her waiting if I were you. The place she spoke of is what we call the Emerald Summit. A path off the main road through the Lower Wilds leads up one of the high stone plateaus; there's a small shrine at the top.\n\nGood luck, {name}. I hope to see you back safe.", sourceObjective = "Speak with Ysondre atop the Emerald Summit in the Lower Wilds.", completion = "You've come.\n\nI am ashamed to ask this of you, {class}, but I've ran from him long enough. Taerar must be stopped.", sourceObjectiveStatus = "unverified-source-field" }
quests[25438] = { id = 25438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Farewell", description = "With that, I am the only one left.\n\nEven if I choose to remain in this world, I cannot rejoin the green flight. But this victory gives me hope. Perhaps, in time, I can find peace in a simple life among mortals.\n\nYou must return to your people. Tell them that the dragons of nightmare are gone, and will no longer threaten these lands.", sourceObjective = "Speak to Adella at Shadebough.", completion = "To be drawn into a fight between dragons...I don't know if you're blessed or cursed.\n\nLady Shandris has heard of all you've done, and has personally sent this reward for your bravery. I'm glad you came back in one piece to receive it.", sourceObjectiveStatus = "unverified-source-field" }
quests[25439] = { id = 25439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeful Heart", description = "These are the naga that took our people. I only need one to interrogate, kill the rest.\n\nShow no mercy, {class}, for they would surely show us none.", sourceObjective = "Kill 10 Zin'jatar Ravagers.", progress = "These naga have ignited a fire in me that is not easily quenched.", completion = "Good to have a real warrior at my side. Too often, my shaman brethren can't seem to stomach the work.", sourceObjectiveStatus = "unverified-source-field" }
quests[25440] = { id = 25440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fathom-Lord Zin'jatar", description = "The Fathom-Lord is here, at the far side of the ruins. He's still injured from our last battle.\n\nI'll leave this pleasure to you. Make sure he doesn't get away this time.", sourceObjective = "Kill Fathom-Lord Zin'jatar.", progress = "Waiting on something? I thought you'd appreciate the opportunity to handle this yourself.\n\nDid I misjudge you?", completion = "And with this, hopefully their attacks on us will calm for a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[25441] = { id = 25441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex", description = "I have no fondness for snakes, and even less so down here. Fortunately for us, the watery elements still bend to my will for now.\n\nTake these globes and throw them at the ground to send the nearby water into a vortex, pulling in all the nearby serpents. The naga will most certainly turn the snakes against us, so keep the orbs close at hand.", sourceObjective = "Use the Globes of Tumultuous Water to trap 30 swarming serpents.", completion = "Too often, we are mistaken for druidic types. Perhaps that's true for some shaman, but do not let yourself be plagued by the ignorant belief that we are always peaceful.\n\nNothing about what I do is harmonious. I command the elements to my will. There is nothing offered in return. I would have it no other way.", sourceObjectiveStatus = "unverified-source-field" }
quests[25442] = { id = 25442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pearl of Wisdom", description = "This pearl is unlike anything you've ever seen before. It radiates light, and if you are not mistaken, it radiates powerful magic as well.\n\nEarthmender Duarn back in Silver Tide Hollow will surely be interested in this.", sourceObjective = "Bring the Luminescent Pearl to Earthmender Duarn in Silvertide Hollow.", progress = "Yes, {class}? Have you found something?", completion = "What is this? A pearl? Much more I think.\n\nThis is exactly what I was looking for, thank you for bringing it to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[25443] = { id = 25443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Name Never Spoken", description = "Did my drought work? You spoke with one of them?\n\nThen you know what to do. The name of their elemental master is written on three firestones scattered throughout the Inferno. Examine each of these stones and we will have the name we need.\n\nHurry! Your precious forest burns!", sourceObjective = "Assemble the true name by examining the three Firestones in the Inferno.", sourceObjectiveStatus = "unverified-source-field" }
